// ═══════════════════════════════════════════
// ⚡ ANIMATION SPEED
// ═══════════════════════════════════════════
function setAnimSpeed(multiplier) {
  document.documentElement.style.setProperty('--anim-speed', multiplier+'');
  localStorage.setItem('animSpeed', multiplier);
  // Apply to all transitions/animations
  if(multiplier === 0) {
    document.documentElement.style.setProperty('--transition','none');
  } else {
    document.documentElement.style.setProperty('--transition', (0.2/multiplier)+'s');
  }
  notify('⚡ Швидкість анімацій: '+(multiplier===2?'Швидко':multiplier===1?'Нормально':multiplier===0.5?'Повільно':'Вимкнено'),'info');
}

function loadAnimSpeed() {
  const saved = parseFloat(localStorage.getItem('animSpeed')||'1');
  setAnimSpeed(saved);
  const sel = document.getElementById('animSpeedSelect');
  if(sel) sel.value = saved;
}

// ═══════════════════════════════════════════
// 🌌 LIVE WALLPAPERS
// ═══════════════════════════════════════════
let liveWpActive = false, liveWpAnim = null;

function toggleLiveWallpaper(type) {
  const canvas = document.getElementById('liveBgCanvas');
  if(!canvas) return;
  if(liveWpActive && liveWpActive===type) {
    liveWpActive = false;
    canvas.classList.remove('active');
    cancelAnimationFrame(liveWpAnim);
    localStorage.setItem('liveWp','none');
    document.querySelectorAll('.live-wallpaper-btn').forEach(b=>b.classList.remove('active'));
    return;
  }
  liveWpActive = type;
  canvas.classList.add('active');
  canvas.width = window.innerWidth; canvas.height = window.innerHeight;
  const ctx = canvas.getContext('2d');
  document.querySelectorAll('.live-wallpaper-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('.live-wallpaper-btn[data-wp="'+type+'"]')?.classList.add('active');
  localStorage.setItem('liveWp', type);
  if(type==='stars') animStars(ctx, canvas);
  else if(type==='matrix') animMatrix(ctx, canvas);
  else if(type==='rain') animRain(ctx, canvas);
}

function animStars(ctx, canvas) {
  const stars = Array.from({length:120},()=>({x:Math.random()*canvas.width,y:Math.random()*canvas.height,r:Math.random()*1.5,s:Math.random()*.5+.1}));
  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    stars.forEach(s=>{
      s.y -= s.s; if(s.y<0) s.y=canvas.height;
      ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle='rgba(255,255,255,'+(0.3+Math.random()*.3)+')'; ctx.fill();
    });
    if(liveWpActive==='stars') liveWpAnim = requestAnimationFrame(draw);
  }
  draw();
}

function animMatrix(ctx, canvas) {
  const cols = Math.floor(canvas.width/16), drops = Array(cols).fill(0);
  const chars = 'アイウエオカキクケコサシスセソ0123456789ABCDEF'.split('');
  function draw() {
    ctx.fillStyle='rgba(0,0,0,.05)'; ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle='#0f0'; ctx.font='14px monospace';
    drops.forEach((y,i)=>{
      ctx.fillText(chars[Math.floor(Math.random()*chars.length)],i*16,y*16);
      if(y*16>canvas.height && Math.random()>.975) drops[i]=0;
      drops[i]++;
    });
    if(liveWpActive==='matrix') liveWpAnim = requestAnimationFrame(draw);
  }
  draw();
}

function animRain(ctx, canvas) {
  const drops = Array.from({length:100},()=>({x:Math.random()*canvas.width,y:Math.random()*canvas.height,s:Math.random()*3+2,l:Math.random()*15+10}));
  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.strokeStyle='rgba(74,158,255,.4)'; ctx.lineWidth=1;
    drops.forEach(d=>{
      ctx.beginPath(); ctx.moveTo(d.x,d.y); ctx.lineTo(d.x-2,d.y+d.l); ctx.stroke();
      d.y+=d.s; d.x-=1;
      if(d.y>canvas.height){d.y=-20;d.x=Math.random()*canvas.width;}
    });
    if(liveWpActive==='rain') liveWpAnim = requestAnimationFrame(draw);
  }
  draw();
}

function loadLiveWallpaper() {
  const saved = localStorage.getItem('liveWp');
  if(saved && saved!=='none') toggleLiveWallpaper(saved);
}



// ═══════════════════════════════════════════
// AUTH SCREEN — particles + stats
// ═══════════════════════════════════════════

function initAuthCanvas() {
  const canvas = document.getElementById('authCanvas');
  if(!canvas) return;
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  const ctx = canvas.getContext('2d');
  const particles = Array.from({length:60}, () => ({
    x: Math.random()*canvas.width,
    y: Math.random()*canvas.height,
    r: Math.random()*2+.5,
    vx: (Math.random()-.5)*.3,
    vy: (Math.random()-.5)*.3,
    alpha: Math.random()*.6+.1,
    color: Math.random() > .6 ? '#d4af37' : '#ffffff'
  }));
  // Floating emojis
  const emojis = ['🎰','🃏','🎲','🎯','💎','🏆','🍀','⭐'];
  const floaters = Array.from({length:8}, (_, i) => ({
    emoji: emojis[i],
    x: Math.random()*canvas.width,
    y: Math.random()*canvas.height,
    vy: -.2 - Math.random()*.3,
    alpha: .12,
    size: 18+Math.random()*14
  }));
  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // BG gradient
    const grad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, 0, canvas.width/2, canvas.height/2, canvas.height*.8);
    grad.addColorStop(0, 'rgba(20,8,0,1)');
    grad.addColorStop(.5, 'rgba(8,3,0,1)');
    grad.addColorStop(1, 'rgba(0,0,0,1)');
    ctx.fillStyle = grad; ctx.fillRect(0,0,canvas.width,canvas.height);
    // Particles
    particles.forEach(p => {
      p.x += p.vx; p.y += p.vy;
      if(p.x<0) p.x=canvas.width; if(p.x>canvas.width) p.x=0;
      if(p.y<0) p.y=canvas.height; if(p.y>canvas.height) p.y=0;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fillStyle = p.color.replace(')', ','+p.alpha+')').replace('rgb','rgba');
      ctx.globalAlpha = p.alpha; ctx.fill(); ctx.globalAlpha=1;
    });
    // Floaters
    floaters.forEach(f => {
      f.y += f.vy; if(f.y < -30) { f.y = canvas.height+30; f.x=Math.random()*canvas.width; }
      ctx.font = f.size+'px serif'; ctx.globalAlpha = f.alpha;
      ctx.fillText(f.emoji, f.x, f.y); ctx.globalAlpha=1;
    });
    // Gold scan line
    const scanY = (Date.now()/30)%canvas.height;
    const scanGrad = ctx.createLinearGradient(0,scanY-20,0,scanY+20);
    scanGrad.addColorStop(0,'rgba(212,175,55,0)');
    scanGrad.addColorStop(.5,'rgba(212,175,55,.03)');
    scanGrad.addColorStop(1,'rgba(212,175,55,0)');
    ctx.fillStyle=scanGrad; ctx.fillRect(0,scanY-20,canvas.width,40);
    requestAnimationFrame(draw);
  }
  draw();
}

let _authJackpotListener = null;
function stopAuthStatsListeners() {
  if(_authJackpotListener) { db.ref('casino_stats/jackpot').off('value', _authJackpotListener); _authJackpotListener = null; }
  stopAuthCoins();
}
function loadAuthStats() {
  db.ref('users').once('value', snap => {
    const users = snap.val()||{};
    const count = Object.keys(users).length;
    const online = Math.max(1, Math.floor(count*0.12 + Math.random()*3));
    const paid = Object.values(users).reduce((s,u)=>s+(u.totalWagered||0), 0);
    const el1 = document.getElementById('authStatPlayers');
    const el2 = document.getElementById('authStatOnline');
    const el3 = document.getElementById('authStatPaid');
    if(el1) el1.textContent = count+'';
    if(el2) el2.textContent = online+'';
    if(el3) el3.textContent = '₴'+formatNumber(Math.max(paid, 1500000));
  });
  // Real jackpot
  if(_authJackpotListener) db.ref('casino_stats/jackpot').off('value', _authJackpotListener);
  _authJackpotListener = snap => {
    const j = snap.val() || 850000;
    const el = document.getElementById('authJackpot');
    if(el) el.textContent = '₴ ' + formatNumber(j);
  };
  db.ref('casino_stats/jackpot').on('value', _authJackpotListener);
  // Floating coins in bg
  initAuthCoins();
  // Password strength listener
  const passInput = document.getElementById('regPass');
  if(passInput) passInput.addEventListener('input', e => {
    const v = e.target.value;
    let strength = 0;
    if(v.length >= 6) strength++;
    if(v.length >= 10) strength++;
    if(/[0-9]/.test(v)) strength++;
    if(/[!@#$%^&*]/.test(v)) strength++;
    const fill = document.getElementById('passStrengthFill');
    if(!fill) return;
    const colors = ['#e74c3c','#f39c12','#d4af37','#3dd68c'];
    fill.style.width = (strength*25)+'%';
    fill.style.background = colors[Math.max(0,strength-1)];
  });
}

let _authCoinsInterval = null;
function initAuthCoins() {
  const container = document.getElementById('authCoins');
  if(!container) return;
  if(_authCoinsInterval) clearInterval(_authCoinsInterval);
  const symbols = ['🪙','💎','🎰','⭐','🃏','🎲','🔔','🍒'];
  _authCoinsInterval = setInterval(() => {
    if(container.children.length > 14) return;
    const el = document.createElement('div');
    el.style.cssText = `position:absolute;left:${Math.random()*100}%;top:-30px;font-size:${16+Math.random()*14}px;animation:coinRain ${5+Math.random()*8}s linear forwards;pointer-events:none;`;
    el.textContent = symbols[Math.floor(Math.random()*symbols.length)];
    container.appendChild(el);
    setTimeout(()=>el.remove(), 14000);
  }, 800);
}
function stopAuthCoins() {
  if(_authCoinsInterval) { clearInterval(_authCoinsInterval); _authCoinsInterval = null; }
}

function spawnWinCoins(amount) {
  const count = amount > 10000 ? 20 : amount > 1000 ? 12 : 6;
  const symbols = ['🪙','💎','🤑','⭐','✨','🏆'];
  for(let i = 0; i < count; i++) {
    setTimeout(()=>{
      const el = document.createElement('div');
      el.className = 'win-coin';
      const startX = 40 + Math.random()*60; // %
      const startY = 40 + Math.random()*30; // %
      el.style.cssText = `left:${startX}%;top:${startY}%;--tx:${(Math.random()-0.5)*200}px;--ty:${-100-Math.random()*200}px;--tr:${(Math.random()-0.5)*720}deg;`;
      el.textContent = symbols[Math.floor(Math.random()*symbols.length)];
      document.body.appendChild(el);
      setTimeout(()=>el.remove(), 1300);
    }, i * 80);
  }
}

