function switchNewsTab(tab) {
  ['news','changelog'].forEach(t => {
    const btn = document.getElementById('ntab-' + t);
    const panel = document.getElementById('np-' + t);
    const isActive = t === tab;
    if(btn) { btn.style.background = isActive ? 'var(--accent)' : 'none'; btn.style.color = isActive ? '#000' : '#666'; }
    if(panel) panel.classList.toggle('hidden', !isActive);
  });
  if(tab === 'changelog') loadChangelog();
  if(tab === 'news') loadNews();
}

function loadChangelog() {
  const el = document.getElementById('changelogList');
  if(!el) return;
  el.innerHTML = '<div style="text-align:center;color:#555;padding:20px 0;">Завантаження...</div>';

  db.ref('changelog').orderByChild('date').limitToLast(20).once('value', snap => {
    const data = snap.val();
    let items = BUILTIN_CHANGELOG.slice(); // always include builtin

    if(data) {
      const dbItems = Object.values(data).sort((a,b) => b.date - a.date);
      // Merge: Firebase first (newer), skip duplicates by version
      const builtinVers = new Set(items.map(i => i.version));
      dbItems.forEach(item => {
        if(!builtinVers.has(item.version)) items.unshift(item);
      });
    }

    items.sort((a,b) => (b.date||0) - (a.date||0));
    el.innerHTML = items.map((item, idx) => buildChangelogCard(item, idx === 0)).join('');

    // Mark as seen
    localStorage.setItem(CHANGELOG_KEY, CURRENT_VERSION);
    const badge = document.getElementById('newsNewBadge');
    if(badge) badge.classList.add('hidden');
  });
}

function buildChangelogCard(item, isLatest) {
  const date = item.date ? new Date(item.date).toLocaleDateString('uk-UA', {day:'numeric',month:'long',year:'numeric'}) : '';
  const newBadge = isLatest ? '<span class="cl-new-badge">НОВИНКА</span>' : '';

  const sections = (item.sections || []).map(sec => `
    <div class="cl-section cl-type-${sec.type}">
      <div class="cl-section-title">${sec.title}</div>
      ${(sec.items||[]).map(it => `
        <div class="cl-item">
          <div class="cl-item-dot"></div>
          <div>${it}</div>
        </div>`).join('')}
    </div>`).join('');

  const stats = item.stats || {};
  const statsHtml = Object.keys(stats).length ? `
    <div class="cl-stats-row">
      ${stats.features ? `<div class="cl-stat"><div class="cl-stat-num">${stats.features}</div><div class="cl-stat-lbl">Нові функції</div></div>` : ''}
      ${stats.fixes    ? `<div class="cl-stat"><div class="cl-stat-num" style="color:#4a9eff">${stats.fixes}</div><div class="cl-stat-lbl">Виправлень</div></div>` : ''}
      ${stats.games    ? `<div class="cl-stat"><div class="cl-stat-num" style="color:#f39c12">${stats.games}</div><div class="cl-stat-lbl">Ігор перевірено</div></div>` : ''}
    </div>` : '';

  return `
    <div class="cl-card">
      <div class="cl-header">
        <div class="cl-ver">v${item.version}</div>
        <div class="cl-meta">
          <div class="cl-title">${item.title||'Оновлення'}${newBadge}</div>
          <div class="cl-date">👨‍💻 ${item.dev||'SlotOK Team'} · ${date}</div>
        </div>
      </div>
      <div class="cl-body">${sections}</div>
      ${statsHtml}
    </div>`;
}

function renderHomeLastUpdate() {
  const el = document.getElementById('homeLastUpdate');
  if(!el) return;
  // Try firebase first, fallback to builtin
  db.ref('changelog').orderByChild('date').limitToLast(1).once('value', snap => {
    let item = BUILTIN_CHANGELOG[0];
    if(snap.val()) {
      const dbItem = Object.values(snap.val())[0];
      if(dbItem && (dbItem.date||0) > (item.date||0)) item = dbItem;
    }
    if(!item) { el.textContent = 'Немає даних'; return; }
    const allItems = (item.sections||[]).flatMap(s => s.items||[]);
    const dateStr = item.date ? new Date(item.date).toLocaleDateString('uk-UA',{day:'numeric',month:'short'}) : '';
    el.innerHTML = `<b style="color:#4cd964;">v${item.version}</b> <span style="color:#333;">${dateStr}</span><br><span style="color:#666;">${allItems[0]||''}</span>${allItems.length>1?`<span style="color:#333;"> +ще ${allItems.length-1}</span>`:''}`;
  });
}

