var _cryptoPortfolio = JSON.parse(localStorage.getItem('slotok_crypto') || '{}');
var CRYPTO_ASSETS = [
  {sym:'BTC', name:'Bitcoin',  emoji:'₿', base:95000, vol:0.04},
  {sym:'ETH', name:'Ethereum', emoji:'Ξ', base:3500,  vol:0.06},
  {sym:'SOL', name:'Solana',   emoji:'◎', base:180,   vol:0.08},
  {sym:'BNB', name:'BNB',      emoji:'⬡', base:600,   vol:0.05},
];
var _cryptoPrices = {};
function updateCryptoPrices() {
  CRYPTO_ASSETS.forEach(function(a) {
    var last = _cryptoPrices[a.sym] || a.base;
    _cryptoPrices[a.sym] = Math.max(last * (1 + (Math.random() - 0.48) * a.vol), a.base * 0.3);
  });
}
function buyCryptoFromBtn(btn) { buyCrypto(btn.dataset.sym, parseInt(btn.dataset.amt)); }
function sellCryptoFromBtn(btn) { sellCrypto(btn.dataset.sym); }

function renderCryptoAssets() {
  var el = document.getElementById('cryptoAssets');
  if(!el) return;
  var pv = 0;
  Object.keys(_cryptoPortfolio).forEach(function(s) { pv += (_cryptoPortfolio[s]||0) * (_cryptoPrices[s]||0); });
  var pvel = document.getElementById('cryptoPortfolioVal');
  if(pvel) pvel.textContent = '₴ ' + formatNumber(Math.round(pv));
  el.innerHTML = CRYPTO_ASSETS.map(function(a) {
    var price  = _cryptoPrices[a.sym] || a.base;
    var owned  = _cryptoPortfolio[a.sym] || 0;
    var chg    = ((price - a.base) / a.base * 100).toFixed(1);
    var isPos  = parseFloat(chg) >= 0;
    var sym    = a.sym;
    var ownedHtml = owned > 0
      ? '<div style="font-size:11px;color:#777;margin-bottom:8px;">У портфелі: '
        + owned.toFixed(6) + ' ' + sym + ' ≈ ₴' + formatNumber(Math.round(owned*price)) + '</div>'
      : '';
    var sellBtn = owned > 0
      ? '<button data-sym="' + sym + '" onclick="sellCryptoFromBtn(this)" '
        + 'style="flex:1;background:rgba(231,76,60,.1);border:1px solid rgba(231,76,60,.2);'
        + 'border-radius:8px;padding:8px;color:#e74c3c;cursor:pointer;font-size:12px;font-weight:700;">Продати</button>'
      : '';
    return '<div style="background:#0d0d0d;border:1px solid #1a1a1a;border-radius:14px;padding:14px;margin-bottom:10px;">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'
      + '<div style="display:flex;align-items:center;gap:10px;">'
      + '<div style="width:40px;height:40px;border-radius:12px;background:rgba(212,175,55,.1);'
      + 'display:flex;align-items:center;justify-content:center;font-size:20px;">' + a.emoji + '</div>'
      + '<div><div style="font-weight:800;">' + sym + '</div>'
      + '<div style="font-size:10px;color:#555;">' + a.name + '</div></div></div>'
      + '<div style="text-align:right;">'
      + '<div style="font-weight:900;font-size:15px;">₴' + formatNumber(Math.round(price)) + '</div>'
      + '<div style="font-size:11px;color:' + (isPos ? '#3dd68c' : '#e74c3c') + ';">'
      + (isPos ? '+' : '') + chg + '%</div></div></div>'
      + ownedHtml
      + '<div style="display:flex;gap:6px;">'
      + '<button data-sym="' + sym + '" data-amt="100" onclick="buyCryptoFromBtn(this)" '
      + 'style="flex:1;background:rgba(61,214,140,.1);border:1px solid rgba(61,214,140,.2);'
      + 'border-radius:8px;padding:8px;color:#3dd68c;cursor:pointer;font-size:12px;font-weight:700;">+100₴</button>'
      + '<button data-sym="' + sym + '" data-amt="500" onclick="buyCryptoFromBtn(this)" '
      + 'style="flex:1;background:rgba(61,214,140,.08);border:1px solid rgba(61,214,140,.15);'
      + 'border-radius:8px;padding:8px;color:#3dd68c;cursor:pointer;font-size:12px;">+500₴</button>'
      + sellBtn
      + '</div></div>';
  }).join('');
}

function buyCrypto(sym, amount) {
  if(!userData.balance || userData.balance < amount) return notify('Недостатньо балансу', 'error');
  var price = _cryptoPrices[sym];
  if(!price) return;
  var qty = amount / price;
  _cryptoPortfolio[sym] = (_cryptoPortfolio[sym] || 0) + qty;
  localStorage.setItem('slotok_crypto', JSON.stringify(_cryptoPortfolio));
  db.ref('users/' + currentUser + '/balance').set(firebase.database.ServerValue.increment(-amount));
  userData.balance -= amount;
  notify('✅ Куплено ' + qty.toFixed(6) + ' ' + sym + ' за ₴' + amount, 'success');
  renderCryptoAssets();
}
function sellCrypto(sym) {
  var qty = _cryptoPortfolio[sym];
  if(!qty) return notify('Немає активу', 'error');
  var value = Math.round(qty * (_cryptoPrices[sym] || 0));
  db.ref('users/' + currentUser + '/balance').set(firebase.database.ServerValue.increment(value));
  userData.balance += value;
  delete _cryptoPortfolio[sym];
  localStorage.setItem('slotok_crypto', JSON.stringify(_cryptoPortfolio));
  notify('💰 Продано ' + sym + ' за ₴' + formatNumber(value), 'success');
  renderCryptoAssets();
}

// 8. P2P ПОЗИКИ
function requestP2PLoan() {
  var from = (document.getElementById('loanFrom') ? document.getElementById('loanFrom').value : '').trim();
  var amount = parseInt(document.getElementById('loanAmount') ? document.getElementById('loanAmount').value : 0) || 0;
  var days = parseInt(document.getElementById('loanDays') ? document.getElementById('loanDays').value : 3) || 3;
  var interestMap = {1:5, 3:8, 7:12, 14:18};
  var interest = interestMap[days] || 8;
  if(!from || !amount) return notify('Заповни всі поля', 'error');
  if(amount < 100) return notify('Мін. 100₴', 'error');
  if(from === currentUser) return notify('Не можна позичати у себе', 'error');
  db.ref('users/' + from).once('value').then(function(snap) {
    if(!snap.exists()) return notify('Гравця не знайдено', 'error');
    var key = db.ref('p2p_loans').push().key;
    db.ref('p2p_loans/' + key).set({borrower:currentUser, lender:from, amount:amount, interest:interest, days:days, status:'pending', dueDate:Date.now()+days*86400000, createdAt:Date.now()});
    db.ref('pm/' + from + '/' + db.ref().push().key).set({from:'💸 Позики', to:from, text:'💸 @' + currentUser + ' просить позику ₴' + formatNumber(amount) + ' на ' + days + ' дн (' + interest + '%). ID: ' + key, ts:Date.now()});
    db.ref('users/' + from + '/pmUnread').set(firebase.database.ServerValue.increment(1));
    notify('📩 Запит надіслано гравцю ' + from, 'success');
  });
}
function repayLoan(key) {
  db.ref('p2p_loans/' + key).once('value').then(function(snap) {
    if(!snap.exists()) return;
    var l = snap.val();
    var repay = Math.round(l.amount * (1 + l.interest / 100));
    if(userData.balance < repay) return notify('Потрібно ₴' + formatNumber(repay), 'error');
    db.ref('users/' + currentUser + '/balance').set(firebase.database.ServerValue.increment(-repay));
    db.ref('users/' + l.lender + '/balance').set(firebase.database.ServerValue.increment(repay));
    db.ref('p2p_loans/' + key).update({status:'repaid', repaidAt:Date.now()});
    notify('✅ Повернено ₴' + formatNumber(repay) + ' (з відсотками)', 'success');
    loadMyLoans();
  });
}
function loadMyLoans() {
  var el = document.getElementById('myLoans');
  if(!el || !currentUser) return;
  db.ref('p2p_loans').orderByChild('borrower').equalTo(currentUser).limitToLast(5).once('value').then(function(snap) {
    var loans = snap.val() || {};
    var active = Object.entries(loans).filter(function(e){ return e[1].status !== 'repaid'; });
    if(!active.length) { el.innerHTML = '<div style="color:#444;">Активних позик немає</div>'; return; }
    el.innerHTML = active.map(function(entry) {
      var k = entry[0], l = entry[1];
      var repay = Math.round(l.amount * (1 + l.interest/100));
      var due = new Date(l.dueDate).toLocaleDateString('uk-UA');
      return '<div style="background:#111;border-radius:10px;padding:10px;margin-bottom:8px;">'
        + '<div style="display:flex;justify-content:space-between;margin-bottom:6px;">'
        + '<div><div style="font-weight:700;">₴' + formatNumber(l.amount) + ' · @' + l.lender + '</div><div style="font-size:10px;color:#555;">' + l.interest + '% · до ' + due + '</div></div>'
        + '<div style="font-size:10px;color:' + (l.status==='active'?'#3dd68c':'#d4af37') + ';font-weight:700;">' + (l.status==='active'?'✅ АКТИВНА':'⏳ Очікує') + '</div></div>'
        + (l.status === 'active' ? '<button onclick="repayLoan(\'' + k + '\')" style="width:100%;background:rgba(61,214,140,.1);border:1px solid rgba(61,214,140,.2);border-radius:8px;padding:7px;color:#3dd68c;cursor:pointer;font-size:12px;">💸 Повернути ₴' + formatNumber(repay) + '</button>' : '')
        + '</div>';
    }).join('');
  });
}


