  const agoStr = ago<1?'щойно':ago<60?ago+'хв тому':Math.floor(ago/60)+'г тому';
  const methodIcon = req.method==='mono'?'🐈':req.method==='telegram'?'✈️':req.method==='usdt'?'₮':'🟢';
