// AI аналіз по правилах (без API)
function generateAiAnalysis(match) {
  const homeOdds = parseFloat(match.homeOdds);
  const awayOdds = parseFloat(match.awayOdds);
  const fav = homeOdds < awayOdds ? match.home : match.away;
  const conf = Math.floor(52 + Math.random()*32);
  const reasons = [
    `${fav} мають найкращу форму в ${match.league} — ${conf}% шанс перемоги за статистикою xG.`,
    `Аналіз 10 останніх матчів: ${fav} виграли 7. Очікую перемогу з ${conf}% впевненістю.`,
    `${fav} домінують у ключових показниках: удари в ціль, позиція і xG. Прогноз: ${conf}%.`,
    `Поточна серія перемог та травмовані гравці суперника дають ${fav} перевагу — ${conf}%.`,
    `Статистика очних зустрічей: ${fav} виграли останні 3 матчі. AI впевненість: ${conf}%.`,
  ];
  return { analysis: reasons[Math.floor(Math.random()*reasons.length)], confidence: conf, aiPick: homeOdds < awayOdds ? 'home' : 'away' };
}

// Спробувати ESPN API, fallback на статичні матчі
async function loadRealSportMatches(sport, btnEl) {
  sportsCurrentSport = sport;
  document.querySelectorAll('.sport-tab-btn').forEach(b => b.classList.remove('active'));
  if(btnEl) btnEl.classList.add('active');

  const listEl = document.getElementById('sportMatchesList');
  const loadEl = document.getElementById('sportsLoadingEl');
  if(listEl) listEl.innerHTML = '';
  if(loadEl) { loadEl.classList.remove('hidden'); loadEl.innerHTML = '<div style="text-align:center;padding:30px;color:#555;font-size:13px;">📡 Завантаження матчів...</div>'; }

  const meta = SPORT_META[sport];
  let matches = [];

  // Try ESPN API
  if(meta && meta.espnUrl) {
    try {
      const res = await fetch(meta.espnUrl + '?limit=10', { signal: AbortSignal.timeout(8000) });
      if(res.ok) {
        const data = await res.json();
        matches = parseESPNScoreboard(data, sport);
      }
    } catch(e) {
      console.log('ESPN API failed:', e.message);
    }
  }

  // Fallback to static matches
  if(!matches.length) {
    matches = (FALLBACK_MATCHES[sport] || FALLBACK_MATCHES.soccer).map(m => ({
      ...m,
      sport,
      ...generateAiAnalysis(m),
      matchTime: randomFutureMatchTime(),
    }));
  }

  // Store
  matches.forEach(m => { realMatches[m.id] = m; });
  if(loadEl) loadEl.classList.add('hidden');
  renderRealMatches(matches);

  // Start live tracker for live ones
  const liveOnes = matches.filter(m => m.isLive);
  if(liveOnes.length && !liveTrackerTimer) startLiveTracker(liveOnes[0]);

  // Load bets
  loadSportMyBets();
}

function randomFutureMatchTime() {
  const now = Date.now();
  const hours = 1 + Math.floor(Math.random() * 72);
  return new Date(now + hours * 3600000).toISOString();
}

function parseESPNScoreboard(data, sport) {
  const events = data.events || [];
  return events.slice(0, 6).map(ev => {
    const comp = ev.competitions?.[0];
    const comps = comp?.competitors || [];
    const home = comps.find(c => c.homeAway==='home') || comps[0] || {};
    const away = comps.find(c => c.homeAway==='away') || comps[1] || {};
    const statusType = ev.status?.type?.name || '';
    const isLive  = statusType === 'STATUS_IN_PROGRESS';
    const isFinal = statusType === 'STATUS_FINAL';
    const minute  = isLive ? (ev.status?.displayClock || '') : null;
    const homeScore = isLive||isFinal ? parseInt(home.score||0) : null;
    const awayScore = isLive||isFinal ? parseInt(away.score||0) : null;

    // Generate odds based on records
    const homeRec = home.records?.[0]?.summary || '';
    const awayRec = away.records?.[0]?.summary || '';
    const homeW = parseInt(homeRec.split('-')[0]) || 8;
    const awayW = parseInt(awayRec.split('-')[0]) || 6;
    const total = homeW + awayW + 4;
    const homeOdds = parseFloat((0.93 / (homeW / total) * 1.1).toFixed(2));
    const awayOdds = parseFloat((0.93 / (awayW / total) * 1.1).toFixed(2));

    const matchObj = {
      id:        'espn_' + ev.id,
      sport,
      home:      home.team?.shortDisplayName || home.team?.displayName || 'Home',
      away:      away.team?.shortDisplayName || away.team?.displayName || 'Away',
      league:    SPORT_META[sport]?.league || sport,
      matchTime: ev.date,
      isLive,
      isFinal,
      liveMinute: minute,
      liveScore: (homeScore!==null) ? { home: homeScore, away: awayScore } : null,
      homeOdds:  Math.max(1.10, Math.min(10, homeOdds)),
      drawOdds:  sport==='soccer' ? parseFloat((2.8+Math.random()*1.2).toFixed(2)) : null,
      awayOdds:  Math.max(1.10, Math.min(10, awayOdds)),
      homeLogo:  home.team?.logo || null,
      awayLogo:  away.team?.logo || null,
    };
    const ai = generateAiAnalysis(matchObj);
    return { ...matchObj, ...ai };
  }).filter(m => m.home !== 'Home');
}

function renderRealMatches(matches) {
  const listEl = document.getElementById('sportMatchesList');
  if(!listEl) return;
  if(!matches.length) {
    listEl.innerHTML = '<div style="text-align:center;color:#555;padding:40px 0;font-size:13px;">Матчів не знайдено. Спробуйте інший вид спорту.</div>';
    return;
  }
  listEl.innerHTML = '';
  matches.forEach(m => {
    const card = document.createElement('div');
    card.className = 'match-card' + (m.isLive ? ' live' : '');
    card.id = 'match-card-' + m.id;
    card.innerHTML = buildMatchCardHTML(m);
    listEl.appendChild(card);
  });
}

function buildMatchCardHTML(m) {
  const isLive     = m.isLive;
  const isFinal    = m.isFinal || m.status === 'finished';
  const sport      = SPORT_META[m.sport] || SPORT_META.soccer;
  const hasDraw    = m.drawOdds !== null && m.drawOdds !== undefined;
  const confColor  = m.confidence >= 70 ? 'var(--green)' : m.confidence >= 55 ? '#f39c12' : '#e74c3c';
  const aiTeam     = m.aiPick==='home' ? shortName2(m.home) : m.aiPick==='away' ? shortName2(m.away) : 'Нічия';

  const timeStr = isFinal ? '🏁 Завершено' :
    isLive ? `<span style="color:#e74c3c;font-weight:bold;animation:pulse2 1s infinite;">🔴 LIVE ${m.liveMinute||''}</span>` :
    m.matchTime ? '🕐 ' + new Date(m.matchTime).toLocaleString('uk-UA',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : '📅 Незабаром';

  const scoreHtml = (isLive || isFinal) && m.liveScore
    ? `<div class="live-score-badge">${m.liveScore.home} : ${m.liveScore.away}</div>`
    : `<div style="padding:8px 14px;color:#555;font-size:12px;">vs</div>`;

  // Team logos (if from ESPN)
  const homeLogo = m.homeLogo ? `<img src="${m.homeLogo}" style="width:28px;height:28px;object-fit:contain;border-radius:4px;" onerror="this.style.display='none'">` : '';
  const awayLogo = m.awayLogo ? `<img src="${m.awayLogo}" style="width:28px;height:28px;object-fit:contain;border-radius:4px;" onerror="this.style.display='none'">` : '';

  const disabled = isFinal ? 'pointer-events:none;opacity:0.5;' : '';

  return `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
      <span style="font-size:11px;color:#555;font-weight:bold;">${sport.icon} ${m.league}</span>
      <span style="font-size:11px;">${timeStr}</span>
    </div>
    <div style="display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:6px;margin-bottom:10px;">
      <div style="text-align:center;">
        ${homeLogo}
        <div style="font-size:13px;font-weight:bold;margin-top:${homeLogo?'4px':'0'};">${m.home}</div>
      </div>
      <div style="text-align:center;">${scoreHtml}</div>
      <div style="text-align:center;">
        ${awayLogo}
        <div style="font-size:13px;font-weight:bold;margin-top:${awayLogo?'4px':'0'};">${m.away}</div>
      </div>
    </div>
    <div class="match-odds-row" style="${disabled}">
      <div class="odds-btn" onclick="openBetSlip('${m.id}','home','${m.home.replace(/'/g,"\\'")}')">
        <div class="odds-label">${shortName2(m.home)}</div><div class="odds-val">${parseFloat(m.homeOdds).toFixed(2)}</div>
      </div>
      ${hasDraw ? `<div class="odds-btn" onclick="openBetSlip('${m.id}','draw','Нічия')">
        <div class="odds-label">Нічия</div><div class="odds-val">${parseFloat(m.drawOdds).toFixed(2)}</div>
      </div>` : ''}
      <div class="odds-btn" onclick="openBetSlip('${m.id}','away','${m.away.replace(/'/g,"\\'")}')">
        <div class="odds-label">${shortName2(m.away)}</div><div class="odds-val">${parseFloat(m.awayOdds).toFixed(2)}</div>
      </div>
    </div>
    <div style="background:#0a0a0a;border-left:3px solid ${confColor};border-radius:0 8px 8px 0;padding:8px 10px;margin-top:8px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px;">
        <span style="font-size:11px;font-weight:bold;color:${confColor};">🤖 ШІ: ${aiTeam}</span>
        <span style="font-size:11px;font-weight:bold;color:${confColor};">${m.confidence||65}%</span>
      </div>
      <div style="font-size:10px;color:#666;">${m.analysis||m.aiAnalysis||''}</div>
      <div style="background:#111;border-radius:4px;height:4px;margin-top:6px;overflow:hidden;">
        <div style="height:100%;background:${confColor};width:${m.confidence||65}%;transition:width 1s;"></div>
      </div>
    </div>
    <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;">
      ${isLive ? `<button onclick="openLiveView('${m.id}')" style="flex:1;min-width:70px;padding:8px;background:rgba(231,76,60,0.12);border:1px solid #e74c3c;border-radius:8px;color:#e74c3c;font-size:11px;font-weight:bold;cursor:pointer;">🔴 LIVE</button>` : ''}
      <button onclick="openMatchTracker('${m.id}')" style="flex:1;min-width:70px;padding:8px;background:rgba(0,119,182,0.15);border:1px solid #0077b6;border-radius:8px;color:#00b4d8;font-size:11px;font-weight:bold;cursor:pointer;">📡 ТРЕКЕР</button>
      <button onclick="openStreamViewer('${m.sport}','${m.home.replace(/'/g,"\'")} vs ${m.away.replace(/'/g,"\'")} ')" style="flex:1;min-width:70px;padding:8px;background:#1a0a2e;border:1px solid #5a20c0;border-radius:8px;color:#c9a0ff;font-size:11px;font-weight:bold;cursor:pointer;">📺 СТРІМ</button>
    </div>
    ${isFinal ? `<div style="text-align:center;margin-top:6px;font-size:11px;color:#555;">🏁 Матч завершено</div>` : ''}
  `;
}

function shortName2(n) { return n && n.length > 12 ? n.slice(0,11)+'…' : (n||''); }

// ---- Live Tracker (ESPN API оновлення) ----
function startLiveTracker(match) {
  if(liveTrackerTimer) clearInterval(liveTrackerTimer);
  liveTrackerTimer = setInterval(async () => {
    try {
      const meta = SPORT_META[match.sport];
      if(!meta?.espnUrl) return;
      const res = await fetch(meta.espnUrl + '?limit=20', { signal: AbortSignal.timeout(6000) });
      if(!res.ok) return;
      const data = await res.json();
      const events = data.events || [];
      const ev = events.find(e => ('espn_'+e.id) === match.id);
      if(!ev) return;
      const comp = ev.competitions?.[0];
      const comps = comp?.competitors || [];
      const home  = comps.find(c=>c.homeAway==='home')||comps[0]||{};
      const away  = comps.find(c=>c.homeAway==='away')||comps[1]||{};
      const statusType = ev.status?.type?.name||'';
      const isLive   = statusType==='STATUS_IN_PROGRESS';
      const isFinal  = statusType==='STATUS_FINAL';
      match.isLive   = isLive;
      match.isFinal  = isFinal;
      match.liveMinute = ev.status?.displayClock||'';
      if(isLive||isFinal) match.liveScore = { home: parseInt(home.score||0), away: parseInt(away.score||0) };
      realMatches[match.id] = match;
      const card = document.getElementById('match-card-'+match.id);
      if(card) card.innerHTML = buildMatchCardHTML(match);
      if(activeLiveMatchId===match.id && match.liveScore) updateLiveView(match, { homeScore:match.liveScore.home, awayScore:match.liveScore.away, minute:match.liveMinute, isFinished:isFinal, events:[] });
      if(isFinal) {
        clearInterval(liveTrackerTimer);
        settleMatchBets(match, { homeScore:match.liveScore?.home||0, awayScore:match.liveScore?.away||0, isFinished:true });
      }
    } catch(e) { console.warn(e); }
  }, 60000);
}

// ---- Settle bets ----
async function settleMatchBets(match, finalScore) {
  const snap = await db.ref('sport_bets').orderByChild('matchId').equalTo(match.id).once('value');
  const bets = snap.val(); if(!bets) return;
  const homeS = finalScore.homeScore, awayS = finalScore.awayScore;
  const winner = homeS > awayS ? 'home' : awayS > homeS ? 'away' : 'draw';
  for(const [betId, bet] of Object.entries(bets)) {
    if(bet.status !== 'pending') continue;
    const won = bet.outcome === winner;
    const payout = won ? Math.floor(bet.amount * bet.odds) : 0;
    await db.ref('sport_bets/'+betId).update({ status: won?'won':'lost', settledAt: Date.now(), finalScore: homeS+':'+awayS });
    if(bet.userId === currentUser) {
      if(won) {
        db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(payout));
        playSound('bonus'); notify(`⚽ ${match.home} ${homeS}:${awayS} ${match.away} — +${formatNumber(payout)}₴!`, 'success');
        if(payout>=500) addToWinFeed('Спорт', payout, bet.odds);
      } else { playSound('loss'); notify(`⚽ ${match.home} ${homeS}:${awayS} ${match.away} — Програш`, 'error'); }
      addToHistory(`Спорт: ${won?'+'+payout:'-'+bet.amount}`);
    }
  }
  db.ref('sport_matches/'+match.id).update({ status:'finished', finalScore: homeS+':'+awayS });
}

// ---- Live View ----
function openLiveView(matchId) {
  const match = realMatches[matchId]; if(!match) return;
  activeLiveMatchId = matchId;
  let modal = document.getElementById('liveViewModal');
  if(!modal) { modal = document.createElement('div'); modal.id='liveViewModal'; modal.style.cssText='position:fixed;top:0;left:0;width:100%;height:100%;background:#030303;z-index:9500;overflow-y:auto;'; document.body.appendChild(modal); }
  modal.innerHTML = buildLiveViewHTML(match);
  modal.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function buildLiveViewHTML(m) {
  const h = m.liveScore?.home ?? 0, a = m.liveScore?.away ?? 0;
  const sport = SPORT_META[m.sport] || SPORT_META.soccer;
  return `<div style="background:#030303;min-height:100vh;padding:16px;padding-bottom:100px;box-sizing:border-box;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;">
      <button onclick="closeLiveView()" style="background:#1a1a1a;border:1px solid #333;border-radius:10px;padding:8px 14px;color:#aaa;font-size:13px;cursor:pointer;">⬅ Назад</button>
      <div style="display:flex;align-items:center;gap:6px;"><div style="width:8px;height:8px;background:#e74c3c;border-radius:50%;animation:pulse2 1s infinite;"></div><span style="color:#e74c3c;font-size:12px;font-weight:bold;">LIVE</span></div>
      <div style="font-size:11px;color:#555;">${sport.icon} ${m.league}</div>
    </div>
    <div style="background:linear-gradient(180deg,#0d1a14,#000);border:1px solid #1a3a1a;border-radius:20px;padding:24px 16px;text-align:center;margin-bottom:16px;">
      <div style="font-size:11px;color:#555;margin-bottom:12px;" id="liveMatchMinute">⏱ ${m.liveMinute||'0'}'</div>
      <div style="display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin-bottom:16px;">
        <div><div style="font-size:14px;font-weight:bold;">${m.home}</div></div>
        <div id="liveScoreBoard" style="background:#000;border:2px solid #1a3a1a;border-radius:16px;padding:12px 20px;">
          <div style="font-size:44px;font-weight:900;font-family:monospace;letter-spacing:4px;">${h}<span style="color:#333;margin:0 4px;">:</span>${a}</div>
        </div>
        <div><div style="font-size:14px;font-weight:bold;">${m.away}</div></div>
      </div>
      <div id="liveStatsBar" style="display:flex;height:6px;border-radius:3px;overflow:hidden;margin-bottom:8px;">
        <div style="background:var(--green);flex:${50};transition:flex 1s;"></div>
        <div style="background:#e74c3c;flex:${50};transition:flex 1s;"></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:10px;color:#555;"><span id="liveHomePoss">50%</span><span>Позиція</span><span id="liveAwayPoss">50%</span></div>
    </div>
    <div style="background:#0d0d0d;border-radius:16px;padding:14px;margin-bottom:14px;">
      <div style="font-size:13px;font-weight:bold;margin-bottom:8px;">📋 Події матчу</div>
      <div id="liveEventsList"><div style="color:#555;font-size:12px;text-align:center;padding:20px;">⏳ Очікуємо події...</div></div>
    </div>
    <div style="background:#0a1a0a;border:1px solid #1a3a1a;border-radius:16px;padding:14px;">
      <div style="font-size:13px;font-weight:bold;color:var(--accent);margin-bottom:10px;">⚡ Швидка ставка</div>
      <div class="match-odds-row" style="gap:6px;">
        <div class="odds-btn" onclick="openBetSlip('${m.id}','home','${m.home.replace(/'/g,"\\'")}')"><div class="odds-label">${shortName2(m.home)}</div><div class="odds-val">${m.homeOdds}</div></div>
        ${m.drawOdds?`<div class="odds-btn" onclick="openBetSlip('${m.id}','draw','Нічия')"><div class="odds-label">X</div><div class="odds-val">${m.drawOdds}</div></div>`:''}
        <div class="odds-btn" onclick="openBetSlip('${m.id}','away','${m.away.replace(/'/g,"\\'")}')"><div class="odds-label">${shortName2(m.away)}</div><div class="odds-val">${m.awayOdds}</div></div>
      </div>
    </div>
  </div>`;
}

function updateLiveView(match, score) {
  const minEl = document.getElementById('liveMatchMinute');
  const sbEl  = document.getElementById('liveScoreBoard');
  const evEl  = document.getElementById('liveEventsList');
  const statEl= document.getElementById('liveStatsBar');
  const hpEl  = document.getElementById('liveHomePoss');
  const apEl  = document.getElementById('liveAwayPoss');
  if(minEl) minEl.textContent = `⏱ ${score.minute||match.liveMinute||0}'`;
  if(sbEl) sbEl.innerHTML = `<div style="font-size:44px;font-weight:900;font-family:monospace;letter-spacing:4px;">${score.homeScore}<span style="color:#333;margin:0 4px;">:</span>${score.awayScore}</div>`;
  if(evEl && score.events?.length) {
    const icons = {goal:'⚽',yellowCard:'🟨',redCard:'🟥',substitution:'🔄',penalty:'⚡'};
    evEl.innerHTML = [...score.events].reverse().map(ev => `<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #111;"><div style="min-width:28px;font-size:10px;color:#555;">${ev.minute}'</div><div style="font-size:16px;">${icons[ev.type]||'📌'}</div><div><div style="font-size:12px;font-weight:bold;">${ev.player||''}</div><div style="font-size:10px;color:#555;">${ev.team==='home'?match.home:match.away}</div></div></div>`).join('');
  }
  const hP = score.homeScore > score.awayScore ? 55 : score.awayScore > score.homeScore ? 45 : 50;
  if(statEl) statEl.innerHTML = `<div style="background:var(--green);flex:${hP};transition:flex 1s;"></div><div style="background:#e74c3c;flex:${100-hP};transition:flex 1s;"></div>`;
  if(hpEl) hpEl.textContent = hP+'%'; if(apEl) apEl.textContent = (100-hP)+'%';
}

function closeLiveView() {
  const m = document.getElementById('liveViewModal');
  if(m) m.classList.add('hidden');
  document.body.style.overflow = '';
  activeLiveMatchId = null;
}

// ---- Bet Slip ----
function openBetSlip(matchId, outcome, team) {
  const match = realMatches[matchId]; if(!match) return;
  const odds = outcome==='home' ? match.homeOdds : outcome==='away' ? match.awayOdds : (match.drawOdds||3.40);
  currentBetSlip = { matchId, outcome, team, odds: parseFloat(odds), match };
  const modal = document.getElementById('betSlipModal');
  document.getElementById('betSlipMatchInfo').innerHTML =
    `<div style="font-size:11px;color:#555;margin-bottom:4px;">${SPORT_META[match.sport]?.icon||'🏆'} ${match.league}</div>
     <div style="font-weight:bold;">${match.home} vs ${match.away}</div>
     <div style="color:var(--green);margin-top:4px;font-size:13px;">Ваша ставка: <b>${team}</b></div>`;
  document.getElementById('betSlipOdds').textContent = '×' + parseFloat(odds).toFixed(2);
  const tipEl = document.getElementById('betSlipAiTip');
  if(tipEl) tipEl.textContent = '🤖 ' + (match.analysis || match.aiAnalysis || 'ШІ аналіз недоступний');
  updateBetSlipPotential();
  modal.classList.remove('hidden');
}

function updateBetSlipPotential() {
  if(!currentBetSlip) return;
  const amt = parseInt(document.getElementById('betSlipAmount')?.value)||0;
  const el = document.getElementById('betSlipPotential');
  if(el) el.textContent = formatNumber(Math.floor(amt * currentBetSlip.odds)) + ' ₴';
}

function closeBetSlip() {
  const m = document.getElementById('betSlipModal'); if(m) m.classList.add('hidden');
  currentBetSlip = null;
}

function confirmRealSportBet() {
  if(!currentBetSlip) return;
  const bet = validateBet(document.getElementById('betSlipAmount').value); if(!bet) return;
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  addWager(bet);
  const betRecord = {
    userId: currentUser, matchId: currentBetSlip.matchId,
    outcome: currentBetSlip.outcome, team: currentBetSlip.team,
    odds: currentBetSlip.odds, amount: bet,
    potential: Math.floor(bet * currentBetSlip.odds),
    status: 'pending',
    matchTitle: `${currentBetSlip.match.home} vs ${currentBetSlip.match.away}`,
    sport: currentBetSlip.match.sport, placedAt: Date.now()
  };
  db.ref('sport_bets').push(betRecord).then((ref) => {
    playSound('click');
    notify(`🎫 Ставку прийнято: ${bet}₴ на ${currentBetSlip.team} (×${currentBetSlip.odds.toFixed(2)})`, 'success');
    closeBetSlip();
    loadSportMyBets();
    if(currentBetSlip?.match && !liveTrackerTimer) startLiveTracker(currentBetSlip.match);
    // Якщо матч зі статичних даних (fallback) — запустити авторозрахунок через 30 секунд
    const matchId = betRecord.matchId;
    if(!matchId.startsWith('espn_')) {
      scheduleQuickSettle(ref.key, betRecord);
    }
  });
}

function loadSportMyBets() {
  const el = document.getElementById('sportMyBets'); if(!el) return;
  db.ref('sport_bets').orderByChild('userId').equalTo(currentUser).limitToLast(10).once('value', snap => {
    const bets = snap.val();
    if(!bets) { el.innerHTML = '<div style="color:#555;font-size:12px;padding:8px 0;">Немає ставок</div>'; return; }
    const sorted = Object.values(bets).sort((a,b) => b.placedAt - a.placedAt);
    el.innerHTML = sorted.map(b => {
      const sc = b.status==='won'?'var(--green)':b.status==='lost'?'var(--red)':'var(--accent)';
      const st = b.status==='won'?`✅ +${formatNumber(b.potential)}₴`:b.status==='lost'?`❌ -${formatNumber(b.amount)}₴`:'⏳ Очікує';
      return `<div style="background:var(--input);border:1px solid var(--border);border-radius:10px;padding:10px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;">
        <div><div style="font-size:12px;font-weight:bold;">${(SPORT_META[b.sport]?.icon||'🏆')} ${b.team} <span style="font-size:10px;color:#555;">×${b.odds}</span></div>
        <div style="font-size:10px;color:#555;">${b.matchTitle||''}</div></div>
        <div style="text-align:right;"><div style="font-size:13px;font-weight:bold;color:${sc};">${st}</div><div style="font-size:10px;color:#555;">${b.amount}₴</div></div>
      </div>`;
    }).join('');
  });
}

// Override old references
window.loadSportMatches = function(sport, btnEl) { loadRealSportMatches(sport, btnEl); };
window.confirmSportBet  = confirmRealSportBet;
// ══════════════════════════════════════════════════════
function checkPendingBetsOnStartup() {
  if(!currentUser) return;
  db.ref('sport_bets').orderByChild('userId').equalTo(currentUser).once('value', snap => {
    const bets = snap.val()||{};
    const pending = Object.entries(bets).filter(([,b])=>b.status==='pending');
    if(!pending.length) return;

    let settled = 0;
    const now = Date.now();
    for(const [betId, bet] of pending) {
      // Якщо ставка старіша 15 хвилин — розраховуємо результат
      const age = now - (bet.placedAt||now);
      if(age < 15 * 60 * 1000) continue; // ставка молодша 15 хвилин — чекаємо

      // Перевіряємо чи є реальний результат у Firebase
      db.ref('sport_matches/'+bet.matchId).once('value', mSnap => {
        const mData = mSnap.val();
        if(mData && mData.status === 'finished' && mData.finalScore) {
          // Є реальний результат — розраховуємо
          const [homeS, awayS] = mData.finalScore.split(':').map(Number);
          resolveOneBet(betId, bet, homeS, awayS);
        } else if(age > 3 * 3600 * 1000) {
          // Ставка старіша 3 годин і немає результату — симулюємо
          simulateAndResolveBet(betId, bet);
        }
      });
      settled++;
    }
    if(settled > 0) notify(`⚙️ Розраховуємо ${settled} ставок...`, 'info');
  });
}

// Розрахунок однієї ставки по відомому рахунку
function resolveOneBet(betId, bet, homeScore, awayScore) {
  const winner = homeScore > awayScore ? 'home' : awayScore > homeScore ? 'away' : 'draw';
  const won = bet.outcome === winner;
  const payout = won ? Math.floor(bet.amount * bet.odds) : 0;
  db.ref('sport_bets/'+betId).update({ status: won?'won':'lost', settledAt: Date.now(), finalScore: homeScore+':'+awayScore });
  if(won) {
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(payout));
    playSound('bonus');
    notify(`🏆 ${bet.matchTitle||'Ставка'} — ВИГРАШ +${formatNumber(payout)}₴!`, 'success');
    if(payout >= 500) addToWinFeed('Спорт', payout, bet.odds);
  } else {
    playSound('loss');
    notify(`😞 ${bet.matchTitle||'Ставка'} — програш -${formatNumber(bet.amount)}₴`, 'error');
  }
  addToHistory(`Спорт: ${won?'+'+payout:'-'+bet.amount}`);
}

// Симуляція результату для матчів без реального рахунку
function simulateAndResolveBet(betId, bet) {
  // Рандомний результат зважений на коефіцієнти
  const homeProb = 1 / (bet.odds || 2);
  const rand = Math.random();
  // Визначаємо переможця по ймовірностях з коефіцієнтів
  let simulatedWinner;
  if(bet.outcome === 'home') {
    // Якщо ставка на home — шанс виграти = 1/homeOdds (з коригуванням)
    simulatedWinner = rand < (1 / (bet.odds * 1.05)) ? 'home' : (rand < 0.65 ? 'away' : 'draw');
  } else if(bet.outcome === 'away') {
    simulatedWinner = rand < (1 / (bet.odds * 1.05)) ? 'away' : (rand < 0.65 ? 'home' : 'draw');
  } else {
    simulatedWinner = rand < (1 / (bet.odds * 1.05)) ? 'draw' : (rand < 0.5 ? 'home' : 'away');
  }
  const won = bet.outcome === simulatedWinner;
  const payout = won ? Math.floor(bet.amount * bet.odds) : 0;
  // Генеруємо правдоподібний рахунок
  const scoreMap = { soccer: [[1,0],[2,1],[1,1],[3,1],[0,1],[0,0],[2,0],[1,2]], basketball: [[108,101],[95,110],[122,115],[98,103]], other: [[1,0],[0,1],[2,1]] };
  const scores = scoreMap[bet.sport] || scoreMap.other;
  let sc;
  if(simulatedWinner === 'home') sc = scores.filter(s=>s[0]>s[1])[0] || [1,0];
  else if(simulatedWinner === 'away') sc = scores.filter(s=>s[0]<s[1])[0] || [0,1];
  else sc = scores.filter(s=>s[0]===s[1])[0] || [1,1];
  db.ref('sport_bets/'+betId).update({ status: won?'won':'lost', settledAt: Date.now(), finalScore: sc[0]+':'+sc[1], simulated: true });
  db.ref('sport_matches/'+bet.matchId).update({ status:'finished', finalScore: sc[0]+':'+sc[1] });
  if(won) {
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(payout));
    playSound('bonus');
    notify(`🏆 ${bet.matchTitle||'Ставка'} — ВИГРАШ +${formatNumber(payout)}₴! (${sc[0]}:${sc[1]})`, 'success');
    if(payout >= 500) addToWinFeed('Спорт', payout, bet.odds);
  } else {
    playSound('loss');
    notify(`😞 ${bet.matchTitle||'Ставка'} (${sc[0]}:${sc[1]}) — програш`, 'error');
  }
  addToHistory(`Спорт: ${won?'+'+payout:'-'+bet.amount}`);
}

// Запустити розрахунок одразу після підтвердження ставки (через 30 сек для демо)
function scheduleQuickSettle(betId, bet) {
  setTimeout(() => {
    db.ref('sport_bets/'+betId).once('value', snap => {
      const b = snap.val();
      if(b && b.status === 'pending') simulateAndResolveBet(betId, b);
    });
  }, 30000); // 30 секунд — для демо/тестування
}

// ╔══════════════════════════════════════════════════════╗
// ║           🪙 COINFLIP PvP                           ║
// ╚══════════════════════════════════════════════════════╝
let cfSelectedSide = 'heads';
let cfCurrentRoom = null;

function switchCfTab(tab) {
  document.getElementById('cftab-create').style.background = tab==='create' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('cftab-create').style.color = tab==='create' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('cftab-join').style.background = tab==='join' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('cftab-join').style.color = tab==='join' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('cf-panel-create').classList.toggle('hidden', tab!=='create');
  document.getElementById('cf-panel-join').classList.toggle('hidden', tab!=='join');
  if(tab==='join') loadCfRooms();
}

function setCfBet(n) {
  document.querySelectorAll('.cf-bet-btn').forEach(b => b.style.borderColor='var(--border)');
  event.target.style.borderColor = 'var(--accent)';
  document.getElementById('cfBetInput').value = n;
}

function selectCfSide(side) {
  cfSelectedSide = side;
  const heads = document.getElementById('cf-side-heads');
  const tails = document.getElementById('cf-side-tails');
  if(side==='heads') {
    heads.style.border='2px solid var(--accent)'; heads.style.background='linear-gradient(135deg,#1a1200,#2d2000)';
    tails.style.border='2px solid var(--border)'; tails.style.background='var(--box)';
  } else {
    tails.style.border='2px solid var(--accent)'; tails.style.background='linear-gradient(135deg,#001a2e,#000d14)';
    heads.style.border='2px solid var(--border)'; heads.style.background='var(--box)';
  }
}

function createCfRoom() {
  const bet = parseInt(document.getElementById('cfBetInput').value);
  if(!bet || bet < 10) return notify('Мінімум ₴10', 'error');
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  const room = { creator: currentUser, bet, side: cfSelectedSide, status: 'waiting', createdAt: Date.now() };
  db.ref('pvp_coinflip').push(room).then(ref => {
    cfCurrentRoom = ref.key;
    notify('🪙 Кімнату створено! Чекаємо суперника...', 'success');
    switchCfTab('join');
    listenCfRoom(ref.key, bet);
  });
}

function loadCfRooms() {
  const el = document.getElementById('cfRoomsList'); if(!el) return;
  el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:20px;font-size:13px;">⏳ Завантаження...</div>';
  db.ref('pvp_coinflip').orderByChild('status').equalTo('waiting').once('value', snap => {
    const rooms = snap.val();
    if(!rooms) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає відкритих кімнат.<br>Створи свою!</div>'; return; }
    const list = Object.entries(rooms).filter(([id, r]) => r.creator !== currentUser);
    if(!list.length) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає кімнат. Перевір пізніше!</div>'; return; }
    el.innerHTML = list.map(([id, r]) => `
      <div style="background:var(--box);border:1px solid var(--border);border-radius:16px;padding:14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;">
        <div>
          <div style="font-size:14px;font-weight:700;">${r.creator} 🆚 ?</div>
          <div style="font-size:11px;color:var(--sub);margin-top:3px;">Ставка: <b style="color:var(--accent);">₴${formatNumber(r.bet)}</b> · ${r.side==='heads'?'🌕 Орел':'🌑 Решка'}</div>
        </div>
        <button onclick="joinCfRoom('${id}',${r.bet},'${r.creator}','${r.side}')" style="background:linear-gradient(135deg,var(--accent),var(--accent2));color:#000;border:none;border-radius:10px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer;margin:0;">Прийняти</button>
      </div>`).join('');
  });
}

function joinCfRoom(roomId, bet, creator, creatorSide) {
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  // Атомарний claim кімнати — якщо два гравці клікнуть "Прийняти" одночасно,
  // тільки ОДИН з них реально приєднається; другий отримає помилку замість
  // подвійного списання і плутанини з переможцем.
  db.ref('pvp_coinflip/'+roomId+'/status').transaction(current => {
    if(current === 'waiting') return 'joining';
    return; // хтось вже забрав цю кімнату
  }, (err, committed) => {
    if(!committed) { notify('Цю кімнату вже зайняв інший гравець', 'error'); loadCfRooms(); return; }
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
    const result = Math.random() < 0.5 ? 'heads' : 'tails';
    const creatorWon = creatorSide === result;
    const winnerUser = creatorWon ? creator : currentUser;
    const payout = Math.floor(bet * 2 * 0.95); // 5% комісія
    db.ref('pvp_coinflip/'+roomId).update({ status:'finished', joiner: currentUser, result, winner: winnerUser, payout, finishedAt: Date.now() });
    // Виплата
    db.ref('users/'+winnerUser+'/balance').set(firebase.database.ServerValue.increment(payout));
    const myWon = winnerUser === currentUser;
    showCfResult(myWon, result, creatorSide, bet, payout, creator);
    if(myWon) addToWinFeed('Coinflip', payout, 2);
  });
}

function listenCfRoom(roomId, bet) {
  db.ref('pvp_coinflip/'+roomId).on('value', snap => {
    const r = snap.val(); if(!r) return;
    if(r.status === 'finished') {
      db.ref('pvp_coinflip/'+roomId).off();
      const myWon = r.winner === currentUser;
      showCfResult(myWon, r.result, r.side, bet, r.payout, r.joiner||'???');
    }
  });
}

function showCfResult(won, result, creatorSide, bet, payout, opponent) {
  const box = document.getElementById('cfResultBox');
  box.classList.remove('hidden');
  box.innerHTML = `
    <div style="font-size:70px;margin-bottom:8px;animation:lbPop .5s ease;">${result==='heads'?'🌕':'🌑'}</div>
    <div style="font-size:22px;font-weight:900;color:${won?'var(--green)':'var(--red)'};margin-bottom:6px;">${won?'🏆 ВИГРАШ!':'😞 ПРОГРАШ'}</div>
    <div style="font-size:16px;color:var(--accent);font-weight:800;">${won?'+₴'+formatNumber(payout):'-₴'+formatNumber(bet)}</div>
    <div style="font-size:11px;color:var(--sub);margin-top:8px;">Монета: ${result==='heads'?'🌕 Орел':'🌑 Решка'} · Суперник: ${opponent}</div>
    <button class="btn-gold" onclick="document.getElementById('cfResultBox').classList.add('hidden');loadCfRooms();" style="margin-top:14px;">🔄 Грати ще</button>`;
  if(won) { playSound('bonus'); triggerWinReaction(payout, 'Coinflip'); }
  else playSound('loss');
}

// ╔══════════════════════════════════════════════════════╗
// ║           ✊ ROCK-PAPER-SCISSORS PvP                ║
// ╚══════════════════════════════════════════════════════╝
let rpsCurrentRoom = null;
let rpsRole = null; // 'creator' | 'joiner'
const RPS_BEATS = { rock:'scissors', scissors:'paper', paper:'rock' };
const RPS_EMOJI = { rock:'✊', scissors:'✌️', paper:'🖐️' };

function switchRpsTab(tab) {
  document.getElementById('rpstab-create').style.background = tab==='create' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('rpstab-create').style.color = tab==='create' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('rpstab-join').style.background = tab==='join' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('rpstab-join').style.color = tab==='join' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('rps-panel-create').classList.toggle('hidden', tab!=='create');
  document.getElementById('rps-panel-join').classList.toggle('hidden', tab!=='join');
  if(tab==='join') loadRpsRooms();
}

function setRpsBet(n) { document.getElementById('rpsBetInput').value = n; }

function createRpsRoom() {
  const bet = parseInt(document.getElementById('rpsBetInput').value);
  if(!bet || bet < 10) return notify('Мінімум ₴10', 'error');
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  const room = { creator: currentUser, bet, status:'waiting', createdAt: Date.now() };
  db.ref('pvp_rps').push(room).then(ref => {
    rpsCurrentRoom = ref.key; rpsRole = 'creator';
    document.getElementById('rps-panel-create').classList.add('hidden');
    document.getElementById('rps-panel-join').classList.add('hidden');
    document.getElementById('rpsGameArea').classList.remove('hidden');
    document.getElementById('rpsStatus').textContent = '⏳ Чекаємо суперника...';
    listenRpsRoom(ref.key, bet, 'creator');
  });
}

function loadRpsRooms() {
  const el = document.getElementById('rpsRoomsList'); if(!el) return;
  el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:20px;font-size:13px;">⏳</div>';
  db.ref('pvp_rps').orderByChild('status').equalTo('waiting').once('value', snap => {
    const rooms = snap.val();
    if(!rooms) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає кімнат.</div>'; return; }
    const list = Object.entries(rooms).filter(([,r]) => r.creator !== currentUser);
    if(!list.length) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає кімнат!</div>'; return; }
    el.innerHTML = list.map(([id, r]) => `
      <div style="background:var(--box);border:1px solid var(--border);border-radius:16px;padding:14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;">
        <div><div style="font-size:14px;font-weight:700;">${r.creator} ✊ ?</div>
        <div style="font-size:11px;color:var(--sub);margin-top:3px;">Ставка: <b style="color:var(--accent);">₴${formatNumber(r.bet)}</b></div></div>
        <button onclick="joinRpsRoom('${id}',${r.bet},'${r.creator}')" style="background:linear-gradient(135deg,#8e44ad,#9b59b6);color:#fff;border:none;border-radius:10px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer;margin:0;">Прийняти</button>
      </div>`).join('');
  });
}

function joinRpsRoom(roomId, bet, creator) {
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  db.ref('pvp_rps/'+roomId+'/status').transaction(current => {
    if(current === 'waiting') return 'joining';
    return;
  }, (err, committed) => {
    if(!committed) { notify('Кімната вже зайнята', 'error'); loadRpsRooms(); return; }
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
    db.ref('pvp_rps/'+roomId).update({ joiner: currentUser, status:'active' });
    rpsCurrentRoom = roomId; rpsRole = 'joiner';
    document.getElementById('rps-panel-join').classList.add('hidden');
    document.getElementById('rpsGameArea').classList.remove('hidden');
    document.getElementById('rpsStatus').textContent = '🎮 Роби хід!';
    listenRpsRoom(roomId, bet, 'joiner');
  });
}

function playRps(choice) {
  if(!rpsCurrentRoom) return;
  const field = rpsRole === 'creator' ? 'creatorMove' : 'joinerMove';
  db.ref('pvp_rps/'+rpsCurrentRoom).update({ [field]: choice, status: 'active' });
  document.getElementById('rpsStatus').textContent = '⏳ Чекаємо ходу суперника...';
  ['rock','scissors','paper'].forEach(c => {
    const el = document.getElementById('rps-'+c);
    if(el) el.style.opacity = c===choice ? '1' : '0.3';
  });
}

function listenRpsRoom(roomId, bet, role) {
  db.ref('pvp_rps/'+roomId).on('value', snap => {
    const r = snap.val(); if(!r) return;
    const cm = r.creatorMove, jm = r.joinerMove;
    if(cm && jm && r.status === 'active') {
      // Атомарний claim — тільки ОДИН з двох клієнтів виграє цю "гонку"
      // і фактично нарахує виплату. Без цього обидва клієнти рахують
      // переможця самостійно і виплата подвоюється щоразу.
      db.ref('pvp_rps/'+roomId+'/status').transaction(current => {
        if(current === 'active') return 'resolving';
        return; // undefined = абортувати, вже хтось забрав
      }, (err, committed) => {
        if(!committed) return; // програли гонку — інший клієнт вже рахує
        let winner;
        if(cm === jm) winner = 'draw';
        else if(RPS_BEATS[cm] === jm) winner = r.creator;
        else winner = r.joiner;
        const payout = Math.floor(bet * 2 * 0.95);
        db.ref('pvp_rps/'+roomId).update({ status:'finished', winner, payout });
        if(winner !== 'draw') db.ref('users/'+winner+'/balance').set(firebase.database.ServerValue.increment(payout));
        else {
          db.ref('users/'+r.creator+'/balance').set(firebase.database.ServerValue.increment(bet));
          db.ref('users/'+r.joiner+'/balance').set(firebase.database.ServerValue.increment(bet));
        }
      });
    } else if(r.status === 'finished' && r.winner !== undefined) {
      // Обидва клієнти реагують на фінальний стан — тільки показ, без повторного нарахування
      db.ref('pvp_rps/'+roomId).off();
      const myMove = role === 'creator' ? cm : jm;
      const oppMove = role === 'creator' ? jm : cm;
      const myWon = r.winner === currentUser;
      const isDraw = r.winner === 'draw';
      const oppEl = document.getElementById('rpsOpponentMove');
      if(oppEl) oppEl.textContent = RPS_EMOJI[oppMove]||'❓';
      showRpsResult(myWon, isDraw, myMove, oppMove, bet, r.payout);
      if(myWon) addToWinFeed('RPS', r.payout, 2);
    } else if(r.status === 'active' && !cm && !jm) {
      const statusEl = document.getElementById('rpsStatus');
      if(statusEl) statusEl.textContent = '🎮 Роби хід!';
    }
  });
}

function showRpsResult(won, draw, myMove, oppMove, bet, payout) {
  const box = document.getElementById('rpsResultBox');
  box.classList.remove('hidden');
  const label = draw ? '🤝 НІЧИЯ!' : won ? '🏆 ВИГРАШ!' : '😞 ПРОГРАШ';
  const color = draw ? 'var(--accent)' : won ? 'var(--green)' : 'var(--red)';
  const amtStr = draw ? '±₴0 (повернуто)' : won ? '+₴'+formatNumber(payout) : '-₴'+formatNumber(bet);
  box.innerHTML = `
    <div style="display:flex;justify-content:center;gap:16px;margin-bottom:12px;">
      <div style="text-align:center;"><div style="font-size:50px;">${RPS_EMOJI[myMove]}</div><div style="font-size:11px;color:var(--sub);">Ти</div></div>
      <div style="font-size:28px;font-weight:900;color:${color};align-self:center;">vs</div>
      <div style="text-align:center;"><div style="font-size:50px;">${RPS_EMOJI[oppMove]}</div><div style="font-size:11px;color:var(--sub);">Суперник</div></div>
    </div>
    <div style="font-size:22px;font-weight:900;color:${color};margin-bottom:6px;">${label}</div>
    <div style="font-size:16px;color:var(--accent);font-weight:800;">${amtStr}</div>
    <button class="btn-gold" onclick="document.getElementById('rpsResultBox').classList.add('hidden');document.getElementById('rpsGameArea').classList.add('hidden');switchRpsTab('create');rpsCurrentRoom=null;rpsRole=null;" style="margin-top:14px;">🔄 Грати ще</button>`;
  if(won) { playSound('bonus'); triggerWinReaction(payout,'RPS'); }
  else if(!draw) playSound('loss');
}

