// ║           🔮 PREDICTION DUEL PvP                   ║
// ╚══════════════════════════════════════════════════════╝
let pdCurrentRoom = null;
let pdRole = null;

function switchPdTab(tab) {
  document.getElementById('pdtab-create').style.background = tab==='create' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('pdtab-create').style.color = tab==='create' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('pdtab-join').style.background = tab==='join' ? 'rgba(212,175,55,.15)' : 'transparent';
  document.getElementById('pdtab-join').style.color = tab==='join' ? 'var(--accent)' : 'var(--sub)';
  document.getElementById('pd-panel-create').classList.toggle('hidden', tab!=='create');
  document.getElementById('pd-panel-join').classList.toggle('hidden', tab!=='join');
  if(tab==='join') loadPdRooms();
}

function setPdBet(n) { document.getElementById('pdBetInput').value = n; }

function createPdRoom() {
  const bet  = parseInt(document.getElementById('pdBetInput').value);
  const guess= parseInt(document.getElementById('pdGuessInput').value);
  if(!bet || bet < 10) return notify('Мінімум ₴10', 'error');
  if(!guess || guess<1 || guess>100) return notify('Число від 1 до 100', 'error');
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  const secret = 1 + Math.floor(Math.random() * 100); // Секретне число
  db.ref('pvp_predict').push({ creator:currentUser, bet, creatorGuess:guess, secret, status:'waiting', createdAt:Date.now() }).then(ref => {
    pdCurrentRoom = ref.key; pdRole = 'creator';
    notify('🔮 Кімнату створено!', 'success');
    switchPdTab('join');
    listenPdRoom(ref.key, bet, guess, 'creator');
  });
}

function loadPdRooms() {
  const el = document.getElementById('pdRoomsList'); if(!el) return;
  el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:20px;">⏳</div>';
  db.ref('pvp_predict').orderByChild('status').equalTo('waiting').once('value', snap => {
    const rooms = snap.val();
    if(!rooms) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає кімнат.</div>'; return; }
    const list = Object.entries(rooms).filter(([,r])=>r.creator!==currentUser);
    if(!list.length) { el.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає кімнат!</div>'; return; }
    el.innerHTML = list.map(([id,r])=>`
      <div style="background:var(--box);border:1px solid var(--border);border-radius:16px;padding:14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;">
        <div><div style="font-size:14px;font-weight:700;">${r.creator} 🔮 ?</div>
        <div style="font-size:11px;color:var(--sub);margin-top:3px;">Ставка: <b style="color:var(--accent);">₴${formatNumber(r.bet)}</b></div></div>
        <button onclick="joinPdRoom('${id}',${r.bet},'${r.creator}')" style="background:linear-gradient(135deg,#0077b6,#00b4d8);color:#fff;border:none;border-radius:10px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer;margin:0;">Прийняти</button>
      </div>`).join('');
  });
}

function joinPdRoom(roomId, bet, creator) {
  if((userData.balance||0) < bet) return notify('Недостатньо коштів', 'error');
  db.ref('pvp_predict/'+roomId+'/status').transaction(current => {
    if(current === 'waiting') return 'joining';
    return;
  }, (err, committed) => {
    if(!committed) { notify('Зайнята', 'error'); loadPdRooms(); return; }
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
    db.ref('pvp_predict/'+roomId).update({ joiner:currentUser, status:'active' });
    pdCurrentRoom = roomId; pdRole = 'joiner';
    document.getElementById('pd-panel-join').classList.add('hidden');
    document.getElementById('pdJoinGuessArea').classList.remove('hidden');
    document.getElementById('pdJoinStatus').textContent = '🔮 Вгадай число від 1 до 100!';
    listenPdRoom(roomId, bet, null, 'joiner');
  });
}

function submitPdGuess() {
  const g = parseInt(document.getElementById('pdJoinGuessInput').value);
  if(!g || g<1 || g>100) return notify('Число від 1 до 100', 'error');
  db.ref('pvp_predict/'+pdCurrentRoom).update({ joinerGuess: g });
  document.getElementById('pdJoinStatus').textContent = '⏳ Чекаємо результату...';
}

function listenPdRoom(roomId, bet, myGuessIfCreator, role) {
  db.ref('pvp_predict/'+roomId).on('value', snap => {
    const r = snap.val(); if(!r) return;
    if(r.joinerGuess && r.creatorGuess && r.secret && r.status === 'active') {
      // Атомарний claim — тільки ОДИН клієнт фактично рахує і платить
      db.ref('pvp_predict/'+roomId+'/status').transaction(current => {
        if(current === 'active') return 'resolving';
        return;
      }, (err, committed) => {
        if(!committed) return;
        const secret = r.secret;
        const cDist = Math.abs(r.creatorGuess - secret);
        const jDist = Math.abs(r.joinerGuess - secret);
        let winner;
        if(cDist < jDist)      winner = r.creator;
        else if(jDist < cDist) winner = r.joiner;
        else                   winner = 'draw';
        const payout = Math.floor(bet * 2 * 0.95);
        db.ref('pvp_predict/'+roomId).update({ status:'finished', winner, payout, secret });
        if(winner !== 'draw') db.ref('users/'+winner+'/balance').set(firebase.database.ServerValue.increment(payout));
        else {
          db.ref('users/'+r.creator+'/balance').set(firebase.database.ServerValue.increment(bet));
          db.ref('users/'+r.joiner+'/balance').set(firebase.database.ServerValue.increment(bet));
        }
      });
    } else if(r.status === 'finished' && r.winner !== undefined) {
      db.ref('pvp_predict/'+roomId).off();
      const secret = r.secret;
      const myGuess = role==='creator' ? r.creatorGuess : r.joinerGuess;
      const oppGuess= role==='creator' ? r.joinerGuess  : r.creatorGuess;
      const myDist  = Math.abs(myGuess - secret);
      const oppDist = Math.abs(oppGuess - secret);
      const myWon   = r.winner === currentUser;
      const isDraw  = r.winner === 'draw';
      showPdResult(myWon, isDraw, secret, myGuess, oppGuess, myDist, oppDist, bet, r.payout, r.creator===currentUser ? r.joiner : r.creator);
      if(myWon) addToWinFeed('Predict', r.payout, 2);
    }
  });
}

function showPdResult(won, draw, secret, myGuess, oppGuess, myDist, oppDist, bet, payout, opponent) {
  document.getElementById('pdJoinGuessArea').classList.add('hidden');
  const box = document.getElementById('pdResultBox');
  box.classList.remove('hidden');
  const color = draw ? 'var(--accent)' : won ? 'var(--green)' : 'var(--red)';
  const label = draw ? '🤝 НІЧИЯ!' : won ? '🏆 ВИГРАШ!' : '😞 ПРОГРАШ';
  const amtStr = draw ? '±₴0' : won ? '+₴'+formatNumber(payout) : '-₴'+formatNumber(bet);
  box.innerHTML = `
    <div style="font-size:50px;font-weight:900;color:var(--accent);font-family:'Orbitron',monospace;margin-bottom:6px;">${secret}</div>
    <div style="font-size:12px;color:var(--sub);margin-bottom:16px;">Загадане число</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
      <div style="background:rgba(${won?'61,214,140':'240,64,96'},.1);border:1px solid rgba(${won?'61,214,140':'240,64,96'},.3);border-radius:14px;padding:12px;text-align:center;">
        <div style="font-size:22px;font-weight:900;color:${won&&!draw?'var(--green)':draw?'var(--accent)':'var(--red)'};">${myGuess}</div>
        <div style="font-size:10px;color:var(--sub);">Твоє число</div>
        <div style="font-size:11px;color:var(--sub);">відстань: ${myDist}</div>
      </div>
      <div style="background:rgba(140,140,140,.08);border:1px solid var(--border);border-radius:14px;padding:12px;text-align:center;">
        <div style="font-size:22px;font-weight:900;">${oppGuess}</div>
        <div style="font-size:10px;color:var(--sub);">${opponent}</div>
        <div style="font-size:11px;color:var(--sub);">відстань: ${oppDist}</div>
      </div>
    </div>
    <div style="font-size:22px;font-weight:900;color:${color};margin-bottom:6px;">${label}</div>
    <div style="font-size:16px;color:var(--accent);font-weight:800;">${amtStr}</div>
    <button class="btn-gold" onclick="document.getElementById('pdResultBox').classList.add('hidden');pdCurrentRoom=null;pdRole=null;switchPdTab('create');" style="margin-top:14px;">🔄 Грати ще</button>`;
  if(won) { playSound('bonus'); triggerWinReaction(payout,'Predict'); }
  else if(!draw) playSound('loss');
}

// ╔══════════════════════════════════════════════════════════════╗
// ║          🏆  НОВИЙ ЛІДЕРБОРД — День / Тиждень / Місяць      ║
// ╚══════════════════════════════════════════════════════════════╝
let lbCurrentMetric = 'wager';
let lbCurrentPeriod = 'day';

function getLbPeriodKey(period) {
  const now = new Date();
  if(period === 'day')   return `day_${now.getFullYear()}_${now.getMonth()+1}_${now.getDate()}`;
  if(period === 'week')  { const d=new Date(now); d.setDate(d.getDate()-d.getDay()); return `week_${d.getFullYear()}_${d.getMonth()+1}_${d.getDate()}`; }
  if(period === 'month') return `month_${now.getFullYear()}_${now.getMonth()+1}`;
  return 'alltime';
}

function getLbResetTime(period) {
  const now = new Date();
  if(period === 'day') { const t = new Date(now); t.setDate(t.getDate()+1); t.setHours(0,0,0,0); return t; }
  if(period === 'week') { const t = new Date(now); t.setDate(t.getDate()+(7-t.getDay())); t.setHours(23,59,59,0); return t; }
  if(period === 'month') { return new Date(now.getFullYear(), now.getMonth()+1, 1); }
  return null;
}

function setLbMetric(metric, el) {
  lbCurrentMetric = metric;
  document.querySelectorAll('.lb-metric-btn').forEach(b => {
    b.style.background = 'var(--box)'; b.style.borderColor = 'var(--border)'; b.style.color = 'var(--sub)';
  });
  el.style.background = 'rgba(212,175,55,.15)'; el.style.borderColor = 'rgba(212,175,55,.4)'; el.style.color = 'var(--accent)';
  loadLeaderboardNew();
}

function setLbPeriod(period, el) {
  lbCurrentPeriod = period;
  ['day','week','month','all'].forEach(p => {
    const btn = document.getElementById('lb-period-'+p);
    if(!btn) return;
    btn.style.background = p===period ? 'rgba(212,175,55,.15)' : 'transparent';
    btn.style.color = p===period ? 'var(--accent)' : 'var(--sub)';
  });
  // Оновити таймер
  const resetEl = document.getElementById('lbResetTimer');
  const labelEl = document.getElementById('lbResetLabel');
  if(period === 'all') {
    if(labelEl) labelEl.style.display = 'none';
  } else {
    if(labelEl) labelEl.style.display = '';
    const resetTime = getLbResetTime(period);
    if(resetTime && resetEl) {
      const diff = resetTime - Date.now();
      const h = Math.floor(diff/3600000), m = Math.floor((diff%3600000)/60000);
      resetEl.textContent = h>0 ? `${h}год ${m}хв` : `${m}хв`;
    }
  }
  const prizes = { day:[5000,2500,1000], week:[50000,25000,10000], month:[200000,100000,50000], all:[null,null,null] };
  const p = prizes[period];
  if(p[0]) {
    document.getElementById('lbPrize1') && (document.getElementById('lbPrize1').textContent = '₴'+formatNumber(p[0]));
    document.getElementById('lbPrize2') && (document.getElementById('lbPrize2').textContent = '₴'+formatNumber(p[1]));
    document.getElementById('lbPrize3') && (document.getElementById('lbPrize3').textContent = '₴'+formatNumber(p[2]));
  }
  loadLeaderboardNew();
}

function loadLeaderboardNew() {
  const podium = document.getElementById('lbPodium');
  const list   = document.getElementById('leaderboardList');
  const myPos  = document.getElementById('lbMyPosition');
  if(list) list.innerHTML = '<div style="text-align:center;color:var(--sub);padding:20px;font-size:13px;">⏳ Завантаження...</div>';
  if(podium) podium.innerHTML = '';

  const metricFields = {
    wager: 'periodWager', wins: 'periodWins', profit: 'periodProfit',
    games: 'periodGames', bigwin: 'stats.biggestWin'
  };
  const metricLabels = {
    wager:'₴', wins:'₴', profit:'₴', games:' ігор', bigwin:'₴'
  };

  if(lbCurrentPeriod === 'all') {
    // Завантажуємо з глобальних даних юзерів
    const fieldMap = { wager:'totalWager', wins:'totalWins', profit:'totalProfit', games:'stats.gamesPlayed', bigwin:'stats.biggestWin' };
    db.ref('users').once('value', snap => {
      const data = snap.val()||{};
      buildLbDisplay(data, fieldMap[lbCurrentMetric]||'totalWager', metricLabels[lbCurrentMetric]||'₴');
    });
  } else {
    // Завантажуємо з лідерборду за період
    const periodKey = getLbPeriodKey(lbCurrentPeriod);
    db.ref(`leaderboards/${periodKey}`).once('value', snap => {
      const data = snap.val()||{};
      if(!Object.keys(data).length) {
        // Якщо немає даних — fallback на globalні
        db.ref('users').once('value', uSnap => {
          buildLbDisplay(uSnap.val()||{}, 'totalWager', '₴');
        });
        return;
      }
      // Перетворюємо в формат {username: {totalWager: val}}
      const mapped = {};
      Object.entries(data).forEach(([user, udata]) => {
        const fieldMap = { wager:'wager', wins:'wins', profit:'profit', games:'games', bigwin:'bigwin' };
        mapped[user] = { totalWager: udata[fieldMap[lbCurrentMetric]]||0, avatar: udata.avatar };
      });
      buildLbDisplay(mapped, 'totalWager', metricLabels[lbCurrentMetric]||'₴');
    });
  }
}

function buildLbDisplay(data, field, suffix) {
  const podium = document.getElementById('lbPodium');
  const list   = document.getElementById('leaderboardList');
  const myPos  = document.getElementById('lbMyPosition');

  let arr = Object.entries(data).map(([name, d]) => {
    let val = field.includes('.') ? field.split('.').reduce((o,k)=>(o||{})[k], d) : d[field];
    return { name, val: val||0, avatar: d.avatar };
  }).filter(u=>u.val>0).sort((a,b)=>b.val-a.val);

  if(!arr.length) {
    if(list) list.innerHTML = '<div style="text-align:center;color:var(--sub);padding:30px;font-size:13px;">Немає даних за цей період.<br>Грай щоб потрапити в рейтинг!</div>';
    if(podium) podium.innerHTML = '';
    return;
  }

  const fmtVal = v => (suffix==='₴'?'₴':'')+formatNumber(Math.floor(v))+(suffix!=='₴'?suffix:'');
  const medals = ['🥇','🥈','🥉'];
  const podColors = [
    { bg:'linear-gradient(135deg,rgba(255,215,0,.15),rgba(255,215,0,.05))', border:'rgba(255,215,0,.35)', color:'#ffd700', h:'140px' },
    { bg:'linear-gradient(135deg,rgba(192,192,192,.1),rgba(192,192,192,.04))', border:'rgba(192,192,192,.3)', color:'#c0c0c0', h:'120px' },
    { bg:'linear-gradient(135deg,rgba(205,127,50,.1),rgba(205,127,50,.04))', border:'rgba(205,127,50,.25)', color:'#cd7f32', h:'110px' }
  ];
  const top3 = arr.slice(0,3);
  // Подіум: 2-1-3
  const podiumOrder = [top3[1], top3[0], top3[2]].filter(Boolean);
  const podiumRanks = [1, 0, 2];
  if(podium) {
    podium.innerHTML = '';
    podiumOrder.forEach((u, pi) => {
      const rank = u === top3[0] ? 0 : u === top3[1] ? 1 : 2;
      const c = podColors[rank];
      const av = u.avatar && u.avatar.length>20 ? `<img src="${u.avatar}" style="width:44px;height:44px;border-radius:50%;border:2px solid ${c.color};object-fit:cover;">` : `<div style="width:44px;height:44px;border-radius:50%;background:var(--input);border:2px solid ${c.color};display:flex;align-items:center;justify-content:center;font-size:20px;">👤</div>`;
      const isMe = u.name === currentUser;
      podium.innerHTML += `
        <div style="background:${c.bg};border:1px solid ${c.border};border-radius:18px;padding:14px 8px;text-align:center;cursor:pointer;${rank===0?'grid-column:2;grid-row:1;':''}${isMe?'box-shadow:0 0 0 2px var(--accent);':''}" onclick="openPublicProfile('${u.name}')">
          <div style="font-size:22px;margin-bottom:6px;">${medals[rank]}</div>
          <div style="display:flex;justify-content:center;margin-bottom:6px;">${av}</div>
          <div style="font-size:12px;font-weight:700;color:${c.color};word-break:break-all;">${u.name}${isMe?' 👈':''}</div>
          <div style="font-size:13px;font-weight:900;color:#fff;margin-top:4px;">${fmtVal(u.val)}</div>
        </div>`;
    });
  }

  // Список 4+
  if(list) {
    list.innerHTML = '';
    arr.slice(3,20).forEach((u,i) => {
      const isMe = u.name === currentUser;
      const av = u.avatar && u.avatar.length>20
        ? `<img src="${u.avatar}" style="width:32px;height:32px;border-radius:50%;object-fit:cover;">`
        : `<div style="width:32px;height:32px;border-radius:50%;background:var(--input);display:flex;align-items:center;justify-content:center;font-size:14px;">👤</div>`;
      list.innerHTML += `
        <div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:${isMe?'rgba(212,175,55,.08)':'var(--box)'};border:1px solid ${isMe?'rgba(212,175,55,.3)':'var(--border)'};border-radius:14px;margin-bottom:6px;cursor:pointer;" onclick="openPublicProfile('${u.name}')">
          <div style="min-width:28px;font-size:13px;font-weight:700;color:var(--sub);">${i+4}.</div>
          ${av}
          <div style="flex:1;"><div style="font-size:13px;font-weight:700;">${u.name}${isMe?' <span style="color:var(--accent);font-size:10px;">(Ти)</span>':''}</div></div>
          <div style="font-size:14px;font-weight:900;color:var(--accent);">${fmtVal(u.val)}</div>
        </div>`;
    });
  }

  // Моя позиція якщо не в топ-20
  const myRank = arr.findIndex(u => u.name === currentUser);
  if(myPos) {
    if(myRank === -1) {
      myPos.innerHTML = '<div style="text-align:center;color:var(--sub);font-size:12px;padding:8px;">Ти ще не в рейтингу. Грай!</div>';
    } else if(myRank >= 20) {
      const u = arr[myRank];
      myPos.innerHTML = `<div style="background:rgba(212,175,55,.08);border:1px solid rgba(212,175,55,.3);border-radius:14px;padding:12px;text-align:center;margin-top:4px;">
        <div style="font-size:12px;color:var(--sub);">Твоя позиція</div>
        <div style="font-size:22px;font-weight:900;color:var(--accent);">#${myRank+1}</div>
        <div style="font-size:13px;color:#fff;">${fmtVal(u.val)}</div>
      </div>`;
    } else {
      myPos.innerHTML = '';
    }
    const lbRank = document.getElementById('lbMyRankLabel');
    if(lbRank && myRank>=0) lbRank.textContent = `Твоя позиція: #${myRank+1}`;
  }
}

// Записуємо статистику у лідерборд при кожній грі
function trackLbStat(type, amount) {
  if(!currentUser) return;
  const periodKey = getLbPeriodKey('day');
  const weekKey   = getLbPeriodKey('week');
  const monthKey  = getLbPeriodKey('month');
  [periodKey, weekKey, monthKey].forEach(key => {
    db.ref(`leaderboards/${key}/${currentUser}/${type}`).set(firebase.database.ServerValue.increment(amount));
  });
  // Профіт додатково пишемо в постійний запис гравця — інакше "Профіт"
  // за весь час немає з чого рахувати (all-time рейтинг читає саме звідси)
  if(type === 'profit') {
    db.ref(`users/${currentUser}/totalProfit`).set(firebase.database.ServerValue.increment(amount));
  }
}

// "Найбільший виграш" — це MAX, не SUM, тому окрема функція з transaction()
function trackLbBigWin(amount) {
  if(!currentUser || !(amount > 0)) return;
  const periodKey = getLbPeriodKey('day');
  const weekKey   = getLbPeriodKey('week');
  const monthKey  = getLbPeriodKey('month');
  [periodKey, weekKey, monthKey].forEach(key => {
    db.ref(`leaderboards/${key}/${currentUser}/bigwin`).transaction(current => Math.max(current||0, amount));
  });
  // Постійний рекорд гравця — це ж значення читає профіль ("Найбільший виграш")
  db.ref(`users/${currentUser}/stats/biggestWin`).transaction(current => Math.max(current||0, amount));
}

// ╔══════════════════════════════════════════════════════════════╗
// ║              🤖  АВТОСТАВКИ                                 ║
// ╚══════════════════════════════════════════════════════════════╝
let abRunning = false;
let abTimer   = null;
let abGame    = 'roulette';
let abColor   = 'red';
let abCashout = 2.0;
let abMartOn  = false;
let abCurrentBet = 0;
let abBaseBet    = 0;
let abStats = { rounds:0, won:0, lost:0 };

function selectAbGame(game, el) {
  abGame = game;
  ['roulette','crash'].forEach(g => {
    const btn = document.getElementById('abgame-'+g);
    if(!btn) return;
    btn.style.border = g===game ? '2px solid '+(g==='roulette'?'rgba(240,64,96,.7)':'rgba(212,175,55,.5)') : '2px solid var(--border)';
    btn.style.opacity = g===game ? '1' : '0.6';
  });
  document.getElementById('abRouletteOpts').classList.toggle('hidden', game!=='roulette');
  document.getElementById('abCrashOpts').classList.toggle('hidden', game!=='crash');
}

function selectAbColor(color, el) {
  abColor = color;
  ['red','black','green'].forEach(c => {
    const btn = document.getElementById('abcolor-'+c);
    if(btn) {
      btn.style.borderWidth = c===color ? '2px' : '1px';
      btn.style.opacity = c===color ? '1' : '0.6';
    }
  });
}

function setAbCashout(v) {
  abCashout = v;
  document.getElementById('abCashoutInput') && (document.getElementById('abCashoutInput').value = v);
}

function toggleAbMart() {
  abMartOn = !abMartOn;
  const toggle = document.getElementById('abMartToggle');
  const thumb  = document.getElementById('abMartThumb');
  const opts   = document.getElementById('abMartOptions');
  if(toggle) toggle.style.background = abMartOn ? 'var(--green)' : 'var(--border)';
  if(thumb)  thumb.style.left = abMartOn ? '20px' : '2px';
  if(thumb)  thumb.style.background = abMartOn ? '#fff' : '#666';
  if(opts)   opts.classList.toggle('hidden', !abMartOn);
}

function startAutobet() {
  if(!currentUser) return notify('Увійди в акаунт','error');
  const bet = parseInt(document.getElementById('abBetAmount').value);
  if(!bet || bet < 1) return notify('Введи суму ставки','error');
  if(abGame === 'roulette' && !abColor) return notify('Обери колір','error');
  abBaseBet = bet;
  abCurrentBet = bet;
  abStats = { rounds:0, won:0, lost:0 };
  abRunning = true;
  document.getElementById('abStartBtn').classList.add('hidden');
  document.getElementById('abStopBtn').classList.remove('hidden');
  document.getElementById('abSettingsBox').style.opacity = '0.5';
  document.getElementById('abSettingsBox').style.pointerEvents = 'none';
  document.getElementById('abStatusIcon').textContent = '▶️';
  document.getElementById('abStatusText').textContent = 'Автоставки запущені';
  document.getElementById('abStatusText').style.color = 'var(--green)';
  const logEl = document.getElementById('abLog');
  if(logEl) logEl.innerHTML = '';
  abRunNextRound();
}

function stopAutobet() {
  abRunning = false;
  if(abTimer) clearTimeout(abTimer);
  abTimer = null;
  document.getElementById('abStartBtn').classList.remove('hidden');
  document.getElementById('abStopBtn').classList.add('hidden');
  document.getElementById('abSettingsBox').style.opacity = '';
  document.getElementById('abSettingsBox').style.pointerEvents = '';
  document.getElementById('abStatusIcon').textContent = '⏸️';
  document.getElementById('abStatusText').textContent = 'Автоставки зупинені';
  document.getElementById('abStatusText').style.color = 'var(--sub)';
  notify('⏹ Автоставки зупинено','info');
}

function abRunNextRound() {
  if(!abRunning) return;
  const maxRounds = parseInt(document.getElementById('abRoundsInput').value) || 0;
  const stopLoss  = parseFloat(document.getElementById('abStopLoss').value) || 0;
  const stopWin   = parseFloat(document.getElementById('abStopWin').value) || 0;
  const netProfit = abStats.won - abStats.lost;
  // Перевірки зупинки
  if(maxRounds > 0 && abStats.rounds >= maxRounds) { stopAutobet(); notify(`✅ Завершено ${abStats.rounds} раундів`,'success'); return; }
  if(stopLoss > 0 && abStats.lost >= stopLoss) { stopAutobet(); notify(`🛑 Стоп-програш: -₴${formatNumber(abStats.lost)}`,'error'); return; }
  if(stopWin > 0 && netProfit >= stopWin) { stopAutobet(); notify(`🎯 Ціль досягнута: +₴${formatNumber(netProfit)}`,'success'); return; }
  if((userData.balance||0) < abCurrentBet) { stopAutobet(); notify('💸 Недостатньо коштів','error'); return; }

  // Виконати раунд
  if(abGame === 'roulette') abPlayRoulette();
  else abPlayCrash();
}

function abPlayRoulette() {
  const bet = abCurrentBet;
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  addWager(bet);
  trackQuest('rouletteBets',1); trackQuest('totalGames',1); trackQuest('weekWager',bet);
  db.ref('users/'+currentUser+'/rouletteBets').set(firebase.database.ServerValue.increment(1));
  trackLbStat('wager', bet); trackLbStat('games', 1);

  const idx = Math.floor(Math.random() * GR_WHEEL_NUMS.length);
  const winNum = GR_WHEEL_NUMS[idx];
  const winColor = GR_WHEEL_COLORS(winNum);
  const won = winColor === abColor;
  const mult = winColor === 'green' ? 14 : 2;
  const payout = won ? Math.floor(bet * mult) : 0;
  if(won) db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(payout));

  abStats.rounds++;
  if(won) { abStats.won += payout - bet; } else { abStats.lost += bet; }
  updateAbStats();
  abAddLog(abStats.rounds, won, bet, payout, winNum, winColor);
  trackLbStat(won?'wins':'loss', won?payout-bet:bet);
  if(won) { trackLbStat('wins', payout); }

  if(abMartOn && !won) {
    const mult2 = parseFloat(document.getElementById('abMartMult').value)||2;
    abCurrentBet = Math.floor(abCurrentBet * mult2);
  } else { abCurrentBet = abBaseBet; }

  abTimer = setTimeout(abRunNextRound, 1800);
}

function abPlayCrash() {
  const bet = abCurrentBet;
  const targetCashout = parseFloat(document.getElementById('abCashoutInput').value) || abCashout;
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-bet));
  addWager(bet);
  trackQuest('totalGames',1); trackQuest('weekWager',bet);
  trackLbStat('wager',bet); trackLbStat('games',1);

  // Симулюємо краш
  const crashPoint = Math.max(1.0, (Math.random()<0.03) ? 1.0 : +((-1/Math.log(Math.random()))*0.99).toFixed(2));
  const won = crashPoint >= targetCashout;
  const payout = won ? Math.floor(bet * targetCashout) : 0;
  if(won) db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(payout));

  abStats.rounds++;
  if(won) { abStats.won += payout - bet; } else { abStats.lost += bet; }
  updateAbStats();
  abAddLog(abStats.rounds, won, bet, payout, '×'+crashPoint.toFixed(2), won?'crash-win':'crash-loss');
  if(won) trackLbStat('wins',payout);

  if(abMartOn && !won) {
    const m = parseFloat(document.getElementById('abMartMult').value)||2;
    abCurrentBet = Math.floor(abCurrentBet * m);
  } else { abCurrentBet = abBaseBet; }

  abTimer = setTimeout(abRunNextRound, 1800);
}

function updateAbStats() {
  document.getElementById('abRoundsDone') && (document.getElementById('abRoundsDone').textContent = abStats.rounds);
  document.getElementById('abTotalWon')   && (document.getElementById('abTotalWon').textContent = '₴'+formatNumber(Math.floor(abStats.won)));
  document.getElementById('abTotalLost')  && (document.getElementById('abTotalLost').textContent = '₴'+formatNumber(Math.floor(abStats.lost)));
}

function abAddLog(round, won, bet, payout, result, color) {
  const logEl = document.getElementById('abLog'); if(!logEl) return;
  const colorEmoji = color==='red'?'🔴':color==='green'?'🟢':color==='black'?'⚫':color==='crash-win'?'🚀':'💥';
  const row = document.createElement('div');
  row.style.cssText = `display:flex;align-items:center;justify-content:space-between;padding:8px 12px;margin-bottom:4px;background:${won?'rgba(61,214,140,.06)':'rgba(240,64,96,.06)'};border:1px solid ${won?'rgba(61,214,140,.2)':'rgba(240,64,96,.2)'};border-radius:10px;`;
  row.innerHTML = `<div style="font-size:12px;color:var(--sub);">#${round} ${colorEmoji} ${result}</div><div style="font-size:13px;font-weight:700;color:${won?'var(--green)':'var(--red)'};">${won?'+₴'+formatNumber(payout-bet):'-₴'+formatNumber(bet)}</div>`;
  logEl.insertBefore(row, logEl.firstChild);
  if(logEl.children.length > 50) logEl.removeChild(logEl.lastChild);
}

// ╔══════════════════════════════════════════════════════════════╗
// ║              🛡️  СТРАХОВКА СТАВОК                          ║
// ╚══════════════════════════════════════════════════════════════╝
const INS_PACKAGES = {
  basic:    { pct:10, comp:0.25, uses:1, label:'Базова' },
  standard: { pct:15, comp:0.50, uses:1, label:'Стандарт' },
  premium:  { pct:25, comp:0.75, uses:3, label:'Преміум' },
};
let insSelectedPackage = 'standard';

function selectInsPackage(pkg, el) {
  insSelectedPackage = pkg;
  ['basic','standard','premium'].forEach(p => {
    const btn = document.getElementById('ins-'+p);
    if(!btn) return;
    const sel = p===pkg;
    if(p==='standard') btn.style.border = sel?'2px solid var(--accent)':'2px solid rgba(212,175,55,.35)';
    else if(p==='premium') btn.style.border = sel?'2px solid #c9a0ff':'2px solid rgba(138,43,226,.3)';
    else btn.style.border = sel?'2px solid #aaa':'2px solid var(--border)';
    btn.style.transform = sel?'scale(1.02)':'scale(1)';
  });
  updateInsCalc();
}

function updateInsCalc() {
  const bet = parseFloat(document.getElementById('insBetAmount').value)||0;
  const calcEl = document.getElementById('insCalc');
  if(!calcEl) return;
  if(!bet) { calcEl.style.display='none'; return; }
  calcEl.style.display = '';
  const pkg = INS_PACKAGES[insSelectedPackage];
  const cost = Math.floor(bet * pkg.pct / 100);
  const comp = Math.floor(bet * pkg.comp);
  document.getElementById('insCostDisplay') && (document.getElementById('insCostDisplay').textContent = '₴'+formatNumber(cost));
  document.getElementById('insCompDisplay') && (document.getElementById('insCompDisplay').textContent = '₴'+formatNumber(comp));
}

function buyInsurance() {
  if(!currentUser) return notify('Увійди в акаунт','error');
  const bet = parseFloat(document.getElementById('insBetAmount').value);
  if(!bet || bet<10) return notify('Введи суму ставки','error');
  const pkg = INS_PACKAGES[insSelectedPackage];
  const cost = Math.floor(bet*pkg.pct/100);
  if((userData.balance||0) < cost) return notify('Недостатньо коштів','error');
  const insurance = { package:insSelectedPackage, betAmount:bet, compensation:Math.floor(bet*pkg.comp), usesLeft:pkg.uses, cost, ts:Date.now(), status:'active', label:pkg.label };
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-cost));
  db.ref('users/'+currentUser+'/insurance').push(insurance).then(() => {
    notify(`🛡️ Страховку "${pkg.label}" куплено за ₴${formatNumber(cost)}!`,'success');
    loadInsActive(); loadInsHistory();
  });
}

function loadInsActive() {
  const box = document.getElementById('insActiveBox');
  const listEl = document.getElementById('insActiveList');
  if(!box||!listEl) return;
  db.ref('users/'+currentUser+'/insurance').orderByChild('status').equalTo('active').once('value', snap => {
    const data = snap.val();
    if(!data) { box.style.display='none'; return; }
    box.style.display = '';
    const items = Object.values(data);
    listEl.innerHTML = items.map(ins => `
      <div style="background:linear-gradient(135deg,rgba(0,119,182,.08),rgba(0,180,216,.04));border:1px solid rgba(0,180,216,.25);border-radius:14px;padding:14px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;">
        <div>
          <div style="font-size:13px;font-weight:700;">🛡️ ${ins.label}</div>
          <div style="font-size:11px;color:var(--sub);">Ставка: ₴${formatNumber(ins.betAmount)} · Компенсація: ₴${formatNumber(ins.compensation)}</div>
          <div style="font-size:11px;color:var(--green);">Залишилось використань: ${ins.usesLeft}</div>
        </div>
      </div>`).join('');
  });
}

function loadInsHistory() {
  const el = document.getElementById('insHistory'); if(!el) return;
  db.ref('users/'+currentUser+'/insurance').limitToLast(10).once('value', snap => {
    const data = snap.val();
    if(!data) { el.innerHTML='<div style="text-align:center;color:var(--sub);font-size:12px;padding:12px;">Немає даних</div>'; return; }
    const items = Object.values(data).reverse();
    el.innerHTML = items.map(ins => {
      const sc = ins.status==='active'?'var(--green)':ins.status==='used'?'var(--accent)':'var(--red)';
      const st = ins.status==='active'?'✅ Активна':ins.status==='used'?'💰 Використана':'❌ Не використана';
      return `<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:var(--box);border:1px solid var(--border);border-radius:10px;margin-bottom:6px;">
        <div><div style="font-size:13px;font-weight:700;">${ins.label||'Страховка'}</div><div style="font-size:10px;color:var(--sub);">₴${formatNumber(ins.betAmount)} · Куплено: ${new Date(ins.ts).toLocaleDateString('uk-UA')}</div></div>
        <div style="font-size:12px;font-weight:700;color:${sc};">${st}</div>
      </div>`;
    }).join('');
  });
}

// Виплата страховки (викликається при програші з будь-якої гри)
function tryClaimInsurance(lossAmount) {
  if(!currentUser) return;
  db.ref('users/'+currentUser+'/insurance').orderByChild('status').equalTo('active').once('value', snap => {
    const data = snap.val(); if(!data) return;
    const entries = Object.entries(data);
    if(!entries.length) return;
    const [insId, ins] = entries[0];
    if(lossAmount > ins.betAmount * 1.5) return; // тільки якщо програш близький до застрахованої суми
    const comp = ins.compensation;
    db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(comp));
    const newUses = ins.usesLeft - 1;
    db.ref('users/'+currentUser+'/insurance/'+insId).update({ usesLeft:newUses, status:newUses>0?'active':'used' });
    notify(`🛡️ Страховка спрацювала! Повернуто ₴${formatNumber(comp)}`, 'success');
  });
}

