async function aiSupportReply(userMsg) {
  const box = document.getElementById('supportChatBox');
  const typing = document.createElement('div');
  typing.id = 'aiTyping';
  typing.style.cssText = 'display:flex;gap:4px;padding:8px 14px;background:#0d1a2e;border-radius:12px;width:fit-content;margin-bottom:8px;';
  typing.innerHTML = '<span style="animation:blink 1s infinite">•</span><span style="animation:blink 1s 0.3s infinite">•</span><span style="animation:blink 1s 0.6s infinite">•</span>';
  if(box) { box.appendChild(typing); box.scrollTop = box.scrollHeight; }

  await new Promise(r => setTimeout(r, 500 + Math.random()*700)); // природня затримка "друку"

  const lower = userMsg.toLowerCase();
  // Рахуємо збіги для кожної теми й беремо найкращу, а не першу-ліпшу —
  // так повідомлення з кількома словами потрапляють у найточнішу тему.
  let best = null, bestScore = 0;
  for(const f of SUPPORT_FAQ) {
    const score = f.keys.reduce((n,k) => n + (lower.includes(k) ? 1 : 0), 0);
    if(score > bestScore) { bestScore = score; best = f; }
  }
  const match = best;
  let reply;
  let needsAdmin = false;
  if(match) {
    reply = match.reply;
  } else {
    reply = '🤔 Не зовсім впевнений, що правильно зрозумів питання. Передав його адміністратору — відповість особисто найближчим часом. А поки можеш глянути розділ «Ще» → там є відповіді на популярні запитання.';
    needsAdmin = true;
  }

  const t2 = document.getElementById('aiTyping'); if(t2) t2.remove();
  db.ref('support_chats/'+currentUser).push({ text: reply, sender:'ai', time: Date.now() });

  if(needsAdmin) {
    // Реальна ескалація адміну через приватні повідомлення
    db.ref('pm/theivankoo/'+db.ref().push().key).set({
      from: '💬 Підтримка', to: 'theivankoo',
      text: `Гравець @${currentUser} задав питання у чаті підтримки: "${userMsg}" — AI не зміг відповісти впевнено.`,
      ts: Date.now()
    });
    db.ref('users/theivankoo/pmUnread').set(firebase.database.ServerValue.increment(1));
  }
}



// ========================
// HOME STATS + JACKPOT
// ========================
function updateHomeStats() {
  if(!currentUser) return;
  const statBets = document.getElementById('homeStatBets');
  const statWins = document.getElementById('homeStatWins');
  const statVip  = document.getElementById('homeStatVip');
  const jackEl   = document.getElementById('homeJackpot');
  if(statBets && userData) {
    animateNumberText(statBets, userData.totalBets||0, '');
    animateNumberText(statWins, userData.totalWins||0, '₴');
  }
  // VIP level
  if(statVip && userData) {
    const wager = userData.totalWager || 0;
    const _VIP_LEVEL_NAMES = ['Iron','Bronze','Silver','Gold','Platinum','Diamond','Master','Supreme'];
    const VIP_REQ    = [0,1000,5000,20000,50000,100000,250000,500000];
    let vipLevel = 0;
    for(let i=_VIP_LEVEL_NAMES.length-1;i>=0;i--) { if(wager>=VIP_REQ[i]){vipLevel=i;break;} }
    statVip.textContent = _VIP_LEVEL_NAMES[vipLevel];
  }
  // Random jackpot
  if(jackEl) {
    const base = 50000 + Math.floor(Math.random()*200000);
    jackEl.textContent = formatNumber(base) + '₴';
  }
}



