function getBpData() {
  return {
    xp:       userData.bpXP        || 0,
    level:    userData.bpLevel     || 0,
    isVip:    userData.bpVip       || false,
    claimed:  userData.bpClaimed   || {},
  };
}

function initBattlePass() {
  if(!userData || !currentUser) return;  // userData ще не завантажено
  const bp = getBpData();
  const level  = bp.level;
  const xp     = bp.xp;
  const xpNext = BP_XP_PER_LEVEL;
  const pct    = Math.min(100, Math.round((xp % xpNext) / xpNext * 100));

  document.getElementById('bpLevel').textContent  = level + 1;
  document.getElementById('bpXP').textContent     = xp % xpNext;
  document.getElementById('bpXPNext').textContent = xpNext;
  document.getElementById('bpProgressBar').style.width = pct + '%';

  const badge = document.getElementById('bpVipBadge');
  if(badge) {
    badge.textContent = bp.isVip ? '👑 VIP' : '⬛ FREE';
    badge.style.background = bp.isVip ? 'linear-gradient(135deg,#b8860b,#d4af37)' : 'linear-gradient(135deg,#333,#555)';
  }

  const vipBox = document.getElementById('bpVipBuyBox');
  if(vipBox) vipBox.style.display = bp.isVip ? 'none' : '';

  renderBattlePassTrack(bp);
}

function renderBattlePassTrack(bp) {
  const el = document.getElementById('battlePassTrack'); if(!el) return;
  const level   = bp.level;  // levels unlocked (0-based index: completed levels)
  const claimed = bp.claimed || {};

  el.innerHTML = `<div style="display:flex;gap:8px;padding:4px 2px;min-width:max-content;">` +
    BP_REWARDS.map(row => {
      const unlocked  = level >= row.lv;
      const claimedF  = claimed['f'+row.lv];
      const claimedV  = claimed['v'+row.lv];
      const isVip     = bp.isVip;
      const isCurrent = level + 1 === row.lv;

      return `<div style="flex-shrink:0;width:110px;border-radius:12px;overflow:hidden;border:2px solid ${isCurrent?'var(--accent)':unlocked?'#3a3a3a':'#1a1a1a'};">
        <!-- Level label -->
        <div style="background:${isCurrent?'rgba(212,175,55,0.2)':'#0a0a0a'};padding:4px 0;text-align:center;font-size:10px;font-weight:bold;color:${isCurrent?'var(--accent)':'#555'};">
          Рівень ${row.lv}
        </div>
        <!-- VIP reward -->
        <div style="padding:8px;background:linear-gradient(135deg,#0d0520,#1a0840);border-bottom:1px solid #1a1a1a;min-height:72px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;${!isVip?'opacity:0.4;':''}">
          <div style="font-size:22px;">${row.vip.icon}</div>
          <div style="font-size:9px;color:#c9a0ff;text-align:center;line-height:1.3;">${row.vip.label}</div>
          ${unlocked && isVip ? (claimedV
            ? `<div style="font-size:9px;color:var(--green);font-weight:bold;">✓ Отримано</div>`
            : `<button onclick="claimBpReward(${row.lv},'v')" style="background:linear-gradient(135deg,#5a20c0,#8040e0);border:none;border-radius:6px;padding:3px 8px;color:#fff;font-size:9px;font-weight:bold;cursor:pointer;margin-top:2px;">Забрати</button>`)
            : (isVip ? `<div style="font-size:9px;color:#333;">🔒</div>` : `<div style="font-size:9px;color:#5a20c0;">👑 VIP</div>`)}
        </div>
        <!-- Free reward -->
        <div style="padding:8px;background:#0a0a0a;min-height:72px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;">
          <div style="font-size:22px;">${row.free.icon}</div>
          <div style="font-size:9px;color:#aaa;text-align:center;line-height:1.3;">${row.free.label}</div>
          ${unlocked ? (claimedF
            ? `<div style="font-size:9px;color:var(--green);font-weight:bold;">✓ Отримано</div>`
            : `<button onclick="claimBpReward(${row.lv},'f')" style="background:linear-gradient(135deg,#1a5a20,#27ae60);border:none;border-radius:6px;padding:3px 8px;color:#fff;font-size:9px;font-weight:bold;cursor:pointer;margin-top:2px;">Забрати</button>`)
            : `<div style="font-size:9px;color:#333;">🔒</div>`}
        </div>
      </div>`;
    }).join('') + `</div>`;

  // Scroll to current level
  setTimeout(() => {
    const cur = el.querySelector('div[style*="accent"]');
    if(cur) cur.scrollIntoView({ behavior:'smooth', inline:'center', block:'nearest' });
  }, 100);
}

let _bpClaimLock = false;
function claimBpReward(lv, track) {
  if(_bpClaimLock) return;  // запобігаємо подвійному кліку
  _bpClaimLock = true;
  setTimeout(() => { _bpClaimLock = false; }, 2000);
  const bp      = getBpData();
  const claimed = bp.claimed || {};
  const key     = track + lv;
  if(claimed[key]) { _bpClaimLock = false; return notify('Вже отримано!', 'info'); }

  const row    = BP_REWARDS.find(r => r.lv === lv);
  if(!row) return;
  const reward = track === 'f' ? row.free : row.vip;
  if(track === 'v' && !bp.isVip) return notify('❌ Потрібен VIP Battle Pass!', 'error');
  if(lv > bp.level) return notify('❌ Рівень ще не досягнуто!', 'error');

  claimed[key] = true;
  const updates = { bpClaimed: claimed };

  // Apply reward
  if(reward.type === 'balance')       updates.balance   = (userData.balance||0)   + reward.val;
  if(reward.type === 'slotiky')       updates.slotiky   = (userData.slotiky||0)   + reward.val;
  if(reward.type === 'freeSlots')     updates.freeSlots = (userData.freeSlots||0) + reward.val;
  if(reward.type === 'freeFortune')   updates.freeFortune = (userData.freeFortune||0) + reward.val;
  if(reward.type === 'minesHints')    updates.minesHints = (userData.minesHints||0) + reward.val;
  if(reward.type === 'crashInsurance')updates.crashInsurance = true;
  if(reward.type === 'vipBoost') {
    const days = reward.val;
    const expiry = Date.now() + days * 86400000;
    const items = userData.slotikyItems || {};
    items['vip_boost_7d'] = { boughtAt: Date.now(), expires: expiry };
    updates.slotikyItems = items;
  }
  if(reward.type === 'lootbox') {
    updates.lootboxes = (userData.lootboxes||0) + reward.val;
  }

  db.ref('users/'+currentUser).update(updates);
  playSound('bonus');
  notify(`🎫 ${reward.icon} ${reward.label} отримано!`, 'success');
  setTimeout(initBattlePass, 400);
}

function addBpXP(amount) {
  if(!currentUser || amount <= 0) return;  // не пишемо при 0 XP
  const bp = getBpData();
  const isVip = bp.isVip;
  const earnedXP = isVip ? amount * 2 : amount; // VIP = double XP
  const newXP    = bp.xp + earnedXP;
  const newLevel = Math.min(Math.floor(newXP / BP_XP_PER_LEVEL), BP_MAX_LEVEL);
  const updates  = { bpXP: newXP };

  if(newLevel > bp.level) {
    updates.bpLevel = newLevel;
    // Notify level up
    setTimeout(() => {
      const t = document.createElement('div');
      t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);z-index:7500;background:linear-gradient(135deg,#0d0520,#2d1060);border:2px solid #c9a0ff;border-radius:16px;padding:14px 24px;text-align:center;box-shadow:0 8px 30px rgba(100,0,200,0.4);animation:slideIn 0.4s ease;';
      t.innerHTML = `<div style="font-size:28px;">🎫</div><div style="font-size:11px;color:#c9a0ff;font-weight:bold;text-transform:uppercase;margin-top:4px;">Battle Pass</div><div style="font-size:18px;font-weight:900;color:#fff;margin-top:2px;">Рівень ${newLevel}!</div>`;
      document.body.appendChild(t);
      playSound('bonus');
      setTimeout(()=>{ t.style.opacity='0'; t.style.transition='0.5s'; setTimeout(()=>t.remove(),500); }, 3000);
    }, 500);
  }

  db.ref('users/'+currentUser).update(updates);
}

function buyVipBattlePass() {
  const cost = 500; // slotiky
  if((userData.slotiky||0) < cost) {
    notify(`❌ Потрібно ${cost} 🪙 Слотіків. У вас: ${userData.slotiky||0}`, 'error');
    return;
  }
  db.ref('users/'+currentUser).update({
    slotiky: (userData.slotiky||0) - cost,
    bpVip:   true,
    bpVipBoughtAt: Date.now(),
    bpVipMethod:   'slotiky'
  });
  playSound('bonus');
  notify('👑 VIP Battle Pass активовано! Тепер ви отримуєте подвійний XP!', 'success');
  setTimeout(initBattlePass, 400);
}

// Admin can grant VIP BP in cashier
function adminGrantVipBp(username) {
  db.ref('users/'+username).update({ bpVip: true, bpVipBoughtAt: Date.now(), bpVipMethod: 'admin' });
  notify(`✅ VIP Battle Pass видано гравцю ${username}`, 'success');
}


