// ── GENERATE UNIQUE CARD NUMBER ──
// ════════════════════════════════════════════════
// ═══ AXIOM BANK CARD INTEGRATION (no self-issue)
// ════════════════════════════════════════════════

// ── CARD DATA ──
// Єдина точка правди: яка картка зараз активна — справжня (Axioma) чи тимчасова партнерська.
// Раніше багато місць коду перевіряли лише userData.virtualCard напряму, тому CVV/блокування/
// заморозка мовчки не працювали для більшості гравців (у них саме тимчасова картка).
function getActiveCard() {
  if(!userData) return null;
  if(userData.virtualCard && userData.virtualCard.axiomLinked) return userData.virtualCard;
  if(userData.tempPartnerCard) return userData.tempPartnerCard;
  return null;
}

function getCardData() {
  if(!userData || !currentUser) return null;
  const card = getActiveCard();
  if(!card || !card.number) return null;
  return card;
}

function getUserCardOrGenerate() {
  const card = userData?.virtualCard;
  if(card && card.number) return card;
  return null;
}

// ── Onboard via Axiom code ──
function confirmAxiomLinkOnboard() {
  const code = (document.getElementById('onboardAxiomCode')?.value||'').trim();
  if(!code || code.length !== 6) return notify('Введи 6-значний код з Аксіоми', 'error');

  db.ref('axiomLinkCodes/' + currentUser).once('value', snap => {
    const data = snap.val();
    if(!data)            return notify('❌ Код не знайдено. Відкрий Аксіому → Профіль → SlotOK', 'error');
    if(data.used)        return notify('❌ Код вже використано. Згенеруй новий в Аксіомі', 'error');
    if(data.code !== code) return notify('❌ Невірний код', 'error');
    if(Date.now() - (data.ts||0) > 10*60*1000) return notify('❌ Код застарів. Згенеруй новий', 'error');

    // Mark code used
    db.ref('axiomLinkCodes/' + currentUser + '/used').set(true);

    // Read Axiom card data and mirror to SlotOK
    db.ref('users/' + currentUser + '/virtualCard').once('value', cardSnap => {
      const axiomCard = cardSnap.val();
      if(!axiomCard || !axiomCard.number) {
        // Axiom card might not exist yet — create minimal mirror
        notify('⚠️ Аксіома картку не знайдено. Зареєструйся в Аксіомі з тим самим ніком', 'error');
        return;
      }

      // Build SlotOK mirror card (same number/cvv/expiry, but with SlotOK fields)
      const updates = {
        'axiomLinked': true,
        'axiomLinkedAt': Date.now(),
        // Keep existing Axiom fields, add SlotOK extras if missing
        'skin': axiomCard.skin || 'gold',
        'ownedSkins': axiomCard.ownedSkins || ['gold'],
        'totalIn': axiomCard.totalIn || 0,
        'totalOut': axiomCard.totalOut || 0,
        'source': 'axiom',
      };

      db.ref('users/' + currentUser + '/virtualCard').update(updates);

      document.getElementById('cardOnboardModal').classList.add('hidden');
      playSound('bonus');
      notify(`🏦 Картка Аксіоми прив'язана до SlotOK!`, 'success');

      // Start freeze sync listener
      startAxiomFreezeSync();

      setTimeout(() => {
        renderCardPanel();
        switchTab('cashier');
        switchCashierTab('card', document.getElementById('ctb-card'));
      }, 600);
    });
  });
}

// ── Real-time freeze sync: Axiom freeze → SlotOK freeze ──
let _freezeSyncListener = null;
function startAxiomFreezeSync() {
  if(_freezeSyncListener) return; // already running
  _freezeSyncListener = db.ref('users/' + currentUser + '/virtualCard/frozen').on('value', snap => {
    const frozen = snap.val();
    // Just re-render card panel to show updated state
    if(typeof renderCardPanel === 'function') setTimeout(renderCardPanel, 200);
    if(frozen === true) {
      // Show warning if user is active
      if(document.getElementById('cashier-panel-card') && !document.getElementById('cashier-panel-card').classList.contains('hidden')) {
        notify('🔒 Картку заблоковано в Аксіомі! Операції недоступні.', 'error');
      }
    }
  });
}

function dismissCardOnboard() {
  document.getElementById('cardOnboardModal').classList.add('hidden');
  localStorage.setItem('cardOnboardDismissed_'+currentUser, '1');
}

// ── CARD ONBOARD CHECK ──
function checkCardOnboarding() {
  if(!currentUser || !userData) return;
  if(userData.virtualCard && userData.virtualCard.number && userData.virtualCard.axiomLinked) return;
  const dismissed = localStorage.getItem('cardOnboardDismissed_'+currentUser);
  if(dismissed) return;
  setTimeout(() => {
    document.getElementById('cardOnboardModal')?.classList.remove('hidden');
  }, 2500);
}

// ── RENDER CARD PANEL ──
let cvvVisible = false;

function copyCardNumber() {
  const card = getCardData();
  if(!card) return;
  navigator.clipboard.writeText(card.number.replace(/\s/g,'')).then(()=>{
    notify('📋 Номер картки скопійовано!', 'success');
  }).catch(()=>{
    notify('Номер: ' + card.number, 'info');
  });
}

// ── BANK ACTIONS ──

function switchCashierTabAndGo(tabId) {
  switchTab('cashier');
  setTimeout(()=>switchCashierTab(tabId, document.getElementById('ctb-'+tabId)), 150);
}
// ── CARD WITHDRAW ──
function submitCardWithdraw() {
  const amount = parseInt(document.getElementById('cwdAmount').value);
  const cardNum = document.getElementById('cwdCardNum').value.trim();
  if(!amount || amount < 200) return notify('Мінімум 200 ₴', 'error');
  if(!cardNum) return notify('Введіть номер картки', 'error');
  if((userData.balance||0) < amount) return notify('Недостатньо коштів', 'error');
  const card = getCardData();
  if(card && card.frozen) return notify('🔒 Картку заблоковано!', 'error');
  // Submit withdraw request same as standard
  const method = document.querySelector('.wm-btn.selected')?.textContent || 'PrivatBank';
  const req = { user:currentUser, amount, card:cardNum, method, status:'pending', ts:Date.now() };
  db.ref('withdrawRequests').push(req);
  db.ref('users/'+currentUser+'/balance').set(firebase.database.ServerValue.increment(-amount));
  // Track card stats
  db.ref('users/'+currentUser+'/virtualCard/totalOut').set(firebase.database.ServerValue.increment(amount));
  // Add to transactions
  addCardTransaction('out', amount, 'Вивід на ' + cardNum.slice(-4), method);
  closeTabModal('cardWithdrawModal');
  notify(`💸 Заявку на ${formatNumber(amount)} ₴ подано!`, 'success');
}

// ── BUY SLOTIKY ──
function renderSlotikyPackages() {
  const grid = document.getElementById('slotikyPackagesGrid');
  if(!grid) return;
  const balEl = document.getElementById('bsmBalance');
  const sEl   = document.getElementById('bsmSlotiky');
  if(balEl) balEl.textContent = formatNumber(userData.balance||0) + ' ₴';
  if(sEl)   sEl.textContent   = (userData.slotiky||0) + ' 🪙';

  grid.innerHTML = SLOTIKY_PACKAGES.map(pkg => {
    const canAfford = (userData.balance||0) >= pkg.price;
    return `<div onclick="purchaseSlotikyPackage(${pkg.count},${pkg.price})" style="background:${canAfford?'linear-gradient(135deg,#0d0520,#2d0d60)':'#0a0a0a'};border:1px solid ${canAfford?'#5a20c0':'#222'};border-radius:14px;padding:14px;text-align:center;cursor:${canAfford?'pointer':'default'};transition:0.2s;${!canAfford?'opacity:0.4':''}">
      <div style="font-size:24px;font-weight:900;color:${canAfford?'#c9a0ff':'#555'};">${pkg.count} 🪙</div>
      <div style="font-size:10px;color:#6040a0;margin:3px 0;">${pkg.label}</div>
      ${pkg.bonus?`<div style="font-size:9px;color:var(--green);">${pkg.bonus}</div>`:''}
      <div style="font-size:13px;font-weight:bold;color:${canAfford?'var(--accent)':'#555'};margin-top:6px;">${formatNumber(pkg.price)} ₴</div>
    </div>`;
  }).join('');
}

function purchaseSlotikyPackage(count, price) {
  if((userData.balance||0) < price) return notify('Недостатньо коштів!', 'error');
  const card = getCardData();
  if(card && card.frozen) return notify('🔒 Картку заблоковано! Розблокуй щоб робити покупки.', 'error');
  db.ref('users/'+currentUser).update({
    balance: firebase.database.ServerValue.increment(-price),
    slotiky: firebase.database.ServerValue.increment(count)
  });
  db.ref('users/'+currentUser+'/virtualCard/totalOut').set(firebase.database.ServerValue.increment(price));
  addCardTransaction('out', price, `Купівля ${count} Слотіків`, 'SlotOK Shop');
  closeTabModal('buySlotikyModal');
  playSound('bonus');
  notify(`🪙 Придбано ${count} Слотіків!`, 'success');
}

// ── CARD SKIN SHOP ──
function renderCardSkinShop() {
  const grid = document.getElementById('skinShopGrid');
  if(!grid) return;
  const card = getCardData();
  const owned = card ? (card.ownedSkins || ['gold','black','blue']) : ['gold','black','blue'];
  const active = card ? (card.skin || 'gold') : 'gold';

  const gradients = {
    gold:     'linear-gradient(135deg,#1a0d00,#6b3d00,#d4af37)',
    black:    'linear-gradient(135deg,#0a0a0a,#2d2d2d)',
    blue:     'linear-gradient(135deg,#0a0a2e,#2244aa)',
    red:      'linear-gradient(135deg,#1a0505,#cc1a1a)',
    green:    'linear-gradient(135deg,#001a00,#1a7a2a)',
    purple:   'linear-gradient(135deg,#0d0520,#6a20c0)',
    titanium: 'linear-gradient(135deg,#1a1a1a,#c0c0c0)',
    galaxy:   'linear-gradient(135deg,#000010,#7000b0)',
  };

  grid.innerHTML = CARD_SKINS.map(skin => {
    const isOwned  = owned.includes(skin.id);
    const isActive = skin.id === active;
    return `<div class="skin-item ${isActive?'active':''} ${!isOwned?'locked':''}"
      onclick="${isOwned ? `applySkin('${skin.id}')` : `buySkin('${skin.id}',${skin.slotiky})`}"
      style="border-color:${isActive?'var(--accent)':'transparent'};">
      <div class="skin-preview" style="background:${gradients[skin.id]||'#111'};">
        <span>${skin.name}</span>
        ${isActive?'<span style="position:absolute;top:6px;right:8px;font-size:16px;">✓</span>':''}
      </div>
      <div class="skin-info">
        <span style="font-size:11px;color:#aaa;">${skin.name}</span>
        <span style="font-size:10px;color:${isOwned?'var(--green)':'#c9a0ff'};">
          ${isActive?'Активний':isOwned?'Встановити':skin.desc}
        </span>
      </div>
      ${!isOwned?`<div class="skin-locked-overlay">🔒</div>`:''}
    </div>`;
  }).join('');
}

function applySkin(skinId) {
  db.ref('users/'+currentUser+'/virtualCard/skin').set(skinId);
  notify('🎨 Скін змінено!', 'success');
  setTimeout(()=>{ renderCardPanel(); renderCardSkinShop(); }, 300);
}

function buySkin(skinId, price) {
  if((userData.slotiky||0) < price) {
    notify(`❌ Потрібно ${price} 🪙. У вас: ${userData.slotiky||0}`, 'error');
    return;
  }
  const card = getCardData();
  const owned = card ? [...(card.ownedSkins||['gold','black','blue']), skinId] : ['gold','black','blue', skinId];
  db.ref('users/'+currentUser).update({
    slotiky: (userData.slotiky||0) - price,
    'virtualCard/ownedSkins': owned,
    'virtualCard/skin': skinId,
  });
  playSound('win');
  notify(`🎨 Скін "${CARD_SKINS.find(s=>s.id===skinId)?.name}" куплено і встановлено!`, 'success');
  setTimeout(()=>{ renderCardPanel(); renderCardSkinShop(); }, 300);
}

// ── CARD TRANSACTIONS ──
function addCardTransaction(direction, amount, title, subtitle) {
  if(!currentUser) return;
  const tx = {
    dir: direction, amount, title, subtitle: subtitle || '',
    ts: Date.now()
  };
  db.ref('users/'+currentUser+'/cardTx').push(tx);
}

function renderCardTransactions(limit) {
  const el = document.getElementById('cardTransactionsList');
  if(!el) return;
  db.ref('users/'+currentUser+'/cardTx').orderByChild('ts').limitToLast(limit||5).once('value', snap => {
    const raw = snap.val();
    if(!raw) { el.innerHTML = '<div style="color:#555;font-size:12px;text-align:center;padding:16px;">Немає операцій</div>'; return; }
    const txs = Object.values(raw).reverse();
    el.innerHTML = txs.map(tx => renderTxItem(tx)).join('');
  });
}

function renderTxItem(tx) {
  const icons = { out:'↗️', in:'↙️', slotiky:'🪙', game:'🎰', cashback:'💰', freeze:'🔒' };
  const color = tx.dir==='in' ? '#4cd964' : '#ff3b30';
  const sign  = tx.dir==='in' ? '+' : '-';
  const dt = new Date(tx.ts).toLocaleString('uk-UA',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
  return `<div class="bank-tx-item">
    <div class="bank-tx-icon" style="background:${tx.dir==='in'?'rgba(76,217,100,0.1)':'rgba(255,59,48,0.1)'};">
      ${icons[tx.dir]||'💳'}
    </div>
    <div class="bank-tx-desc">
      <div class="bank-tx-title">${tx.title||'Операція'}</div>
      <div class="bank-tx-time">${tx.subtitle||''} • ${dt}</div>
    </div>
    <div class="bank-tx-amount ${tx.dir==='in'?'plus':'minus'}">${sign}${formatNumber(tx.amount)} ₴</div>
  </div>`;
}
